const BOOK_T=(mp)=>(mp<=12?0:mp<=20?1:mp<=30?2:3);
for(const g of GONGFA)ITEMS.push({id:"b_"+g.id,k:"book",t:[0,1,3,4][g.grade],name:`《${g.name}》`,v:[400,2000,8000,25000][g.grade],fx:{learn:g.id},desc:`${["黄", "玄", "地", "天"][g.grade]}阶功法，修炼 ×${g.rate}。${g.desc}`});
for(const a of ARTS)if(a.id!=="a_slash"&&a.id!=="a_fire")ITEMS.push({id:"b_"+a.id,k:"book",t:BOOK_T(a.mp),name:`《${a.name}》`,v:[300,1200,5000,15000][BOOK_T(a.mp)],fx:{learn:a.id},desc:`神通秘籍，威力 ×${a.mult}，耗灵 ${a.mp}。${a.desc}`});
const ITEM_MAP=Object.fromEntries(ITEMS.map((i)=>[i.id,i]));
function itemOf(id){
return ITEM_MAP[id]??null;
}

const AFFIXES=[
{id:"sharp",name:"锋锐",st:"atk",base:0.06},
{id:"solid",name:"坚固",st:"def",base:0.06},
{id:"vital",name:"厚血",st:"hp",base:0.06},
{id:"swift",name:"轻灵",st:"spd",base:0.05},
{id:"keen",name:"锐意",st:"crit",base:0.02},
{id:"spirit",name:"通灵",st:"mp",base:0.08},
{id:"dao",name:"悟道",st:"rate",base:0.02},
];

// ---- lib/game/stats.js
const OFFLINE_CAP_HOURS=[12,24,36];
const STAMINA_MAX=10;
const STAMINA_REGEN_HOURS=0.5;
const TOX_DECAY_PER_DAY=10;
const STAMINA_PILL_DAILY=2; 
const TOX_MAX=100;
function basePower(r,s){
if(r>=ASCEND_REALM)return REALMS[REALMS.length-1].power*3;
return REALMS[r].power*(1+0.12*s);
}

function petCombatMult(c,petMod=1){
const p=c.pet;
if(!p||p.trip)return{atk:0,hp:0};
const lvm=(1+(p.lv??0)*0.1)*[1,1.3,1.69][Math.min(2,p.ev??0)];
return{atk:(p.atk??0)*lvm*petMod,hp:(p.hp??0)*lvm*petMod};
}


function petPowerBonus(c,petMod=1){
const m=petCombatMult(c,petMod);
return Math.max(0,Math.min(0.6,0.11*(m.atk+m.hp) / 2-0.05));
}
function mods(c){
const p=pathOf(c.path)?.mods??{};
const sub=subOf(c.sub)?.mods??{};
const gf=gongfaOf(c.gf);
const gm=gf.mods??{};
return{p,sub,gf,gm};
}
function equipStats(c){
const out={hp:0,atk:0,def:0,mp:0,spd:0,crit:0,rate:0,spell:0,bt:0,trib:0,elem:null};
const artifactMult=pathOf(c.path)?.mods?.artifact??1;
for(const slot of["w","a","r"]){
const iid=c.eq?.[slot];
if(!iid)continue;
const it=(c.inv?.arts??[]).find((a)=>a.iid===iid);
if(!it)continue;
const def=itemOf(it.id);
if(!def)continue;
const qm=1+(it.q-1)*0.08; 
for(const[k,v]of Object.entries(def.st??{})){
if(k==="rate"||k==="crit"||k==="spell"||k==="bt")out[k]+=v*qm;
else out[k]+=v*qm*artifactMult;
}
for(const af of it.af??[]){
if(af.st==="rate"||af.st==="crit"||af.st==="spell")out[af.st]+=af.v;
else out[af.st]+=af.v*artifactMult;
}
for(const rn of it.rn??[]){
if(rn.st==="rate"||rn.st==="crit"||rn.st==="spell")out[rn.st]+=rn.v;
else out[rn.st]+=rn.v*artifactMult;
}
if(def.trib)out.trib+=def.trib;
if(slot==="w"&&def.elem)out.elem=def.elem;
}
return out;
}

function deriveStats(c){
const{p,sub,gf,gm}=mods(c);
const P=basePower(c.r,c.s);
const eq=equipStats(c);
const legacyMult=1+Math.min(1.0,(c.legacy??0)*0.02);
const wuMult=1+Math.min(0.5,(c.wu??0)*0.01);
let hp=10*P*(p.hp??1)*(gm.hp??1)*legacyMult+eq.hp;
let atk=P*(p.atk??1)*(gm.atk??1)*legacyMult+eq.atk;
let def=0.5*P*(p.def??1)*(gm.def??1)*legacyMult+eq.def;
let mp=5*P*(p.mp??1)*(gm.mp??1)+eq.mp;
let spd=(10+6*c.r+c.s)*(p.spd??1)*(gm.spd??1)+eq.spd;
let crit=0.05+(p.crit??0)+(gm.crit??0)+eq.crit;
let spell=1+((p.spell??1)-1)+((gm.spell??1)-1)+eq.spell;

const now=c._now??0;
const inj=(c.dbf?.injury??0)>now;
const heart=(c.dbf?.heart??0)>now;
if(inj){hp*=0.7;atk*=0.7;def*=0.7;}
if(heart){mp*=0.7;crit=Math.max(0,crit-0.03);}

const root=rootInfo(c.root);
let rate=root.mult;
let gfRate=gf.rate;
if(gf.zaBonus&&(c.root.t==="za"||c.root.t==="si"))gfRate*=gf.zaBonus;

if(gf.elem&&c.root.e.includes(gf.elem))gfRate*=1.1;
rate*=gfRate;
rate*=p.rate??1;
rate*=sub.rate??1;
rate*=1+eq.rate;
rate*=[1,1.05,1.15][c.array??0];
rate*=wuMult*legacyMult;
const vm=vipMod(c);
rate*=vm.rate; 
rate*=1+Math.min(0.2,(c.sectLv??0)*0.02)+(c.sectB?.cj??0)*0.01;
if((c.dbf?.qi??0)>now)rate*=0.5; 
if(inj)rate*=0.6;
if(heart)rate*=0.75;
if((c.tox??0)>70)rate*=0.6;
else if((c.tox??0)>40)rate*=0.85;
const bt=(gf.bt??0)+eq.bt+Math.min(0.1,(c.wu??0)*0.005)+vm.bt;
const trib=(gf.trib??0)+eq.trib+(c.flags?.trib_insight?0.05:0)+vm.trib;
const lifeMult=(p.life??1)*(gm.life??1);
const staminaMax=STAMINA_MAX+(sub.stamina??0);
const elem=eq.elem??gf.elem??c.root.e[0]??null;
const power=Math.round((hp / 10+atk*2+def*2+mp / 5+spd*3+crit*500)*(1+petPowerBonus(c,p.pet??1)));
return{
hp:Math.round(hp),atk:Math.round(atk),def:Math.round(def),mp:Math.round(mp),spd:Math.round(spd),
crit:+crit.toFixed(3),spell:+spell.toFixed(2),rate:+rate.toFixed(3),ratePerHour:Math.round(REALMS[Math.min(c.r,REALMS.length-1)].rate*rate),
bt:+bt.toFixed(3),trib:+trib.toFixed(2),lifeMult,staminaMax,elem,power,
pathMods:p,subMods:sub,injured:inj,heart,qi:(c.dbf?.qi??0)>now,
};
}
function buildUnit(c,st,opts={}){
const arts=(c.eqArts??["a_slash"]).map(artOf);
let pet=null;
if(c.pet&&!c.pet.trip){
const m=petCombatMult(c,st.pathMods.pet??1);
pet={
name:c.pet.name,elem:c.pet.elem,
atk:Math.round(st.atk*m.atk),
maxHp:Math.round(st.hp*m.hp),
};
pet.hp=Math.round(pet.maxHp*(opts.petFrac??c.pet.hpP??1));
}
return{
name:c.name,uid:c.uid,
hp:Math.round(st.hp*(opts.hpFrac??c.hpP??1)),maxHp:st.hp,
mp:Math.round(st.mp*(opts.mpFrac??c.mpP??1)),maxMp:st.mp,
atk:st.atk,def:st.def,spd:st.spd,crit:st.crit,spell:st.spell,elem:st.elem,
arts,pet,path:c.path,interrupt:st.pathMods.interrupt??0,array:st.pathMods.array??0,
talis:st.pathMods.talis??1,
};
}

function buildSnapshot(c,st){
const u=buildUnit(c,st,{hpFrac:1,mpFrac:1});
return{
hp:u.maxHp,mp:u.maxMp,atk:u.atk,def:u.def,spd:u.spd,crit:u.crit,sp:u.spell,el:u.elem,
ar:(c.eqArts??["a_slash"]).slice(0,3),pet:u.pet?{n:u.pet.name,e:u.pet.elem,a:u.pet.atk,h:u.pet.maxHp}:null,
pa:c.path??null,hs:c.sectB?.hs||undefined,
};
}
function unitFromSnapshot(p){
const b=p.b??{};
const pet=b.pet?{name:b.pet.n,elem:b.pet.e,atk:b.pet.a,hp:b.pet.h,maxHp:b.pet.h}:null;
return{
name:p.n,uid:p.uid,hp:b.hp??100,maxHp:b.hp??100,mp:b.mp??50,maxMp:b.mp??50,
atk:b.atk??10,def:Math.round((b.def??5)*(1+(b.hs??0)*0.01)),spd:b.spd??10,crit:b.crit??0.05,spell:b.sp??1,elem:b.el??null,
arts:(b.ar??["a_slash"]).map(artOf),pet,path:b.pa??null,interrupt:0,array:0,talis:1,
};
}
function offlineCapMs(c){
return(OFFLINE_CAP_HOURS[Math.min(2,c.array??0)]+vipMod(c).off+((c.biguan??0)>(c._now??0)?12:0))*HOUR;
}

// ---- lib/game/events2.js
const CST=8*HOUR;
const cst=(now)=>{const d=new Date(now+CST);return{wd:d.getUTCDay(),h:d.getUTCHours()};};

const EV_DAY={
1:{id:"shuangxiu",name:"双修日",desc:"修炼 ×1.5",rate:1.5},
4:{id:"shuangxiu",name:"双修日",desc:"修炼 ×1.5",rate:1.5},
3:{id:"fangshi",name:"坊市集",desc:"坊市八折",disc:0.8},
6:{id:"mijing",name:"秘境开放",desc:"秘境 +1 次",dg:1},
0:{id:"mijing",name:"秘境开放",desc:"秘境 +1 次",dg:1},
};
const EV_HOUR={from:20,to:22,id:"yaochao",name:"妖潮",desc:"游历掉落 ×1.5、遭妖更多（去游历页，不是副本）",drop:1.5,enc:0.5};
const ENC_BASE=0.3; 
function dayEvent(now){
const{wd,h}=cst(now);
const list=[];
if(EV_DAY[wd])list.push(EV_DAY[wd]);
const hot=h>=EV_HOUR.from&&h<EV_HOUR.to;
if(hot)list.push(EV_HOUR);
return{
list:list.map((e)=>({id:e.id,name:e.name,desc:e.desc})),
rate:EV_DAY[wd]?.rate??1,disc:EV_DAY[wd]?.disc??1,dg:EV_DAY[wd]?.dg??0,drop:hot?EV_HOUR.drop:1,enc:hot?EV_HOUR.enc:ENC_BASE,hot,
next:hot?null:`${EV_HOUR.from}:00 妖潮`,
};
}

function eventBonusHours(from,now){
let bonus=0;
let t=from;
while(t<now){
const dayStart=Math.floor((t+CST) / DAY)*DAY-CST;
const dayEnd=dayStart+DAY;
const seg=Math.min(now,dayEnd)-t;
const r=EV_DAY[new Date(t+CST).getUTCDay()]?.rate??1;
if(r>1)bonus+=(seg / HOUR)*(r-1);
t=dayEnd;
}
return bonus;
}

const dayEventOfDay=(day)=>dayEvent(day*DAY+4*HOUR);

// ---- lib/game/char.js
const SCHEMA=1;
const START_AGE=16;
const NAME_RE= /^[一-龥A-Za-z0-9_·]{2,8}$/;
function validName(name){
return typeof name==="string"&&NAME_RE.test(name);
}
function newCharacter({uid,name,now,seed,legacy}){
const rng=makeRng(seed);
const root=rollRoot(rng);
const lg=legacy??{pts:0,lives:0};
const c={
v:SCHEMA,uid,name,born:now,created:now,
r:0,s:0,xp:0,root,rerolls:3,
path:null,sub:null,respec:0,wu:0,
hpP:1,mpP:1,tox:0,toxAt:now,
st:10,stAt:now,ls:50+lg.pts*20,
last:now,breathAt:0,breathN:0,
buffs:[],dbf:{},lifeBonus:0,
gf:"g_tuna",gfs:["g_tuna"],arts:["a_slash","a_fire"],eqArts:["a_slash","a_fire"],
eq:{w:null,a:null,r:null},inv:{stack:{p_huixue:2,m_lingcao:3},arts:[]},ic:0,
pet:null,array:0,flags:{},once:{},ev:null,trib:null,ac:0,
daily:{d:dayKey(now),exp:0,arena:0,boss:0,breath:0,login:false,claim:{},bs:null,bo:null,br:null},
stats:{fights:0,wins:0,kills:0,explores:0,pills:0,crafts:0,bt:0,btFail:0,tribs:0,sells:0,dons:0,bossHits:0,aw:0},
season:{n:0,ss:0,ar:1000,w:0,l:0,sync:now},
sect:null,sectLv:0,legacy:lg.pts,lives:(lg.lives??0)+1,
dead:null,ascended:false,title:null,
};
if(lg.pts>=5)c.inv.stack.p_xiqi=2;
if(lg.pts>=10)c.gfs.push("g_qingfeng");
if(lg.keep?.gf)for(const g of lg.keep.gf)if(!c.gfs.includes(g))c.gfs.push(g);
if(lg.keep?.arts)for(const a of lg.keep.arts)if(!c.arts.includes(a))c.arts.push(a);
return c;
}
function ageOf(c,now){
return START_AGE+Math.floor(((now-c.born) / DAY)*YEARS_PER_DAY);
}
function lifespanOf(c,st){
const base=c.r>=ASCEND_REALM?99999:REALMS[c.r].life;
return Math.round(base*(st?.lifeMult??1))+(c.lifeBonus??0);
}
function xpNeed(c){
if(c.r>=ASCEND_REALM)return 1;
return stageNeed(c.r,c.s);
}

function settle(c,now){
c._now=now;
const out={gained:0,hours:0,died:false,stamina:0};


const d=dayKey(now);
if(c.daily.d!==d){
c.daily={d,exp:0,arena:0,boss:0,breath:0,login:false,claim:{},bs:null,bo:null,br:null};
}
if(c.dead)return out;
const st=deriveStats(c);

const elapsed=Math.max(0,now-(c.last??now));
const effective=Math.min(elapsed,offlineCapMs(c));
if(effective>0&&c.r<ASCEND_REALM){
const from=now-effective;
const baseRate=REALMS[c.r].rate*st.rate;
let hours=effective / HOUR;
let bonusHours=0;
for(const b of c.buffs??[]){
if(b.k!=="rate")continue;
const s0=Math.max(from,b.from??0);
const s1=Math.min(now,b.until??0);
if(s1>s0)bonusHours+=((s1-s0) / HOUR)*(b.m-1);
}
bonusHours+=eventBonusHours(from,now); 
const gained=baseRate*(hours+bonusHours);
const need=xpNeed(c);
const cap=need*1.5;
const before=c.xp;
c.xp=Math.min(cap,c.xp+gained);
out.gained=Math.round(c.xp-before);
out.hours=+hours.toFixed(2);
out.capped=elapsed>effective;
}
c.last=now;
c.buffs=(c.buffs??[]).filter((b)=>(b.until??0)>now);

const regenH=STAMINA_REGEN_HOURS / (st.subMods.stRegen??1);
const ticks=Math.floor((now-(c.stAt??now)) / (regenH*HOUR));
if(ticks>0){
const before=c.st;
c.st=Math.min(st.staminaMax,c.st+ticks);
c.stAt=(c.stAt??now)+ticks*regenH*HOUR;
if(c.st>=st.staminaMax)c.stAt=now;
out.stamina=c.st-before;
}
if(c.st>st.staminaMax)c.st=st.staminaMax;

const toxDays=(now-(c.toxAt??now)) / DAY;
if(toxDays>0&&c.tox>0){
c.tox=Math.max(0,c.tox-toxDays*TOX_DECAY_PER_DAY);
}
c.toxAt=now;


if(c.dbf)for(const k of Object.keys(c.dbf))if((c.dbf[k]??0)<=now)delete c.dbf[k];

const restH=elapsed / HOUR;
c.hpP=Math.min(1,(c.hpP??1)+restH);
c.mpP=Math.min(1,(c.mpP??1)+restH);

const age=ageOf(c,now);
const life=lifespanOf(c,st);
if(age>=life&&c.r<ASCEND_REALM){
c.dead={t:now,age,cause:"寿元耗尽"};
out.died=true;
}
return out;
}
function summary(c,now){
const st=deriveStats(c);
const need=xpNeed(c);
return{
uid:c.uid,name:c.name,r:c.r,s:c.s,realm:realmName(c.r,c.s),xp:Math.round(c.xp),need,
pct:Math.min(100,Math.round((c.xp / need)*100)),canBt:c.xp>=need,
root:c.root,path:c.path,sub:c.sub,wu:c.wu,ls:Math.round(c.ls),st:c.st,stMax:st.staminaMax,
hp:Math.round(st.hp*c.hpP),mp:Math.round(st.mp*c.mpP),stats:st,
tox:Math.round(c.tox),age:ageOf(c,now),life:lifespanOf(c,st),lives:c.lives,legacy:c.legacy,
gf:c.gf,eqArts:c.eqArts,eq:c.eq,pet:c.pet,array:c.array,sect:c.sect,sectLv:c.sectLv,
daily:c.daily,dbf:c.dbf,buffs:c.buffs,dead:c.dead,ascended:c.ascended,title:c.title,
season:c.season,trib:c.trib?{n:c.trib.n,i:c.trib.i,hp:c.trib.hp,mp:c.trib.mp,target:c.trib.target}:null,
ev:c.ev?c.ev.id:null,rerolls:c.rerolls,breathAt:c.breathAt,now,vip:c.vip|0,
farm:farmBadge(c,now),
dg:c.dg?c.dg.f:0,wx:c.wx&&c.wx.d===dayKey(now)?c.wx.sc:0,
};
}

function farmBadge(c,now){
const plots=c.farm?.plots??[];
let alert=0,ready=0;
for(const p of plots){
if(!p)continue;
if(p.ev||(p.hurt??0)>=2)alert++;
else if(now>=p.ready)ready++;
}
return{n:plots.length,alert,ready};
}

