// ---- lib/game/codex.js
const CODEX_KINDS=[["pill","丹药"],["mat","材料"],["art","法宝"],["tal","符箓"],["egg","灵兽"],["book","典籍"],["misc","杂物"],["mon","妖兽"]];
const nameOf=(id)=>itemOf(id)?.name??id;
const pct=(x)=>`${Math.round(x * 100)}%`;

function fxLine(i){
const f=i.fx??{};
const out=[];
if(f.xp)out.push(`修为 +${f.xp}`);
if(f.heal)out.push(`回血 ${pct(f.heal)}`);
if(f.mp)out.push(`回灵 ${pct(f.mp)}`);
if(f.st)out.push(`体力 +${f.st}`);
if(f.rate)out.push(`修炼 ×${f.rate.mult}（${f.rate.hours} 小时）`);
if(f.bt)out.push(`突破 +${pct(f.bt)}`);
if(f.life)out.push(`寿元 +${f.life}`);
if(f.tox)out.push(`丹毒 +${f.tox}`);
if(f.dmg)out.push(`开场一击 ×${f.dmg}${f.elem ? "（" + f.elem + "）" : ""}`);
if(f.shield)out.push(`护盾 ${pct(f.shield)}`);
if(f.stun)out.push(`眩晕 ${pct(f.stun)}`);
if(f.seed)out.push(`种下 ${f.h ?? "?"} 小时得 ${nameOf(f.seed)}`);
if(f.rune)out.push(`符纹：${f.rune}`);
if(f.learn){
const sid=f.learn;
const from=MONSTERS.filter((m)=>(m.drops??[]).some((d)=>d[0]===sid)||(sid.startsWith("a_")&&m.arts.includes(sid))).map((m)=>m.name);
out.push(from.length?`出处：${from.join("、")}${from.length > 1 ? "" : ""}（妖兽会什么神通就可能掉什么秘籍；奇遇与秘境亦有）`:"出处：奇遇、秘境");
out.push("用后习得；已学或道途不合的可去拍卖行上拍，也可在功法页把已学的封存成册");
}
return out.join(" · ");
}
let cache=null;
function codexView(){
if(cache)return cache;
const items=ITEMS.map((i)=>({
id:i.id,k:i.k,t:i.t??0,name:i.name,v:i.v??0,desc:i.desc??"",
slot:i.slot??null,st:i.st??null,
pet:i.pet?{name:i.pet.name,elem:i.pet.elem,atk:i.pet.atk,hp:i.pet.hp}:null,
fx:fxLine(i)||null,
}));
const mons=MONSTERS.map((m)=>({
id:m.id,name:m.name,t:m.t??0,elem:m.elem??null,icon:m.icon??"",boss:!!m.boss,desc:m.desc??"",
m:m.m??null,region:REGIONS.filter((r)=>r.tier===(m.t??0)).map((r)=>r.name).join("、")||null,
drops:(m.drops??[]).map(([id,p,n])=>({name:nameOf(id),p:Math.round(p*100),n})),
}));
cache={kinds:CODEX_KINDS,items,mons};
return cache;
}

// ---- lib/game/inventory.js
const STACK_CAP=60;
const ART_CAP=30;
const STACKABLE=new Set(["mat","pill","tal","egg","misc","book"]);
function countOf(c,id){
return c.inv.stack[id]??0;
}
function hasItems(c,list){
return(list??[]).every(([id,n])=>n<=0||countOf(c,id)>=n);
}
function removeItems(c,list){
for(const[id,n]of list??[]){
if(n<=0)continue;
const left=(c.inv.stack[id]??0)-n;
if(left>0)c.inv.stack[id]=left;
else delete c.inv.stack[id];
}
}

const bagFree=(def)=>!!def&&(def.k==="book"||!!def.fx?.seed);
const bagUsed=(c)=>Object.keys(c.inv.stack).filter((id)=>!bagFree(itemOf(id))).length;

function addStack(c,id,n){
const def=itemOf(id);
if(!def||!STACKABLE.has(def.k)||n<=0)return false;
if(!(id in c.inv.stack)&&!bagFree(def)&&bagUsed(c)>=STACK_CAP)return false;
c.inv.stack[id]=(c.inv.stack[id]??0)+n;
return true;
}

function rollAffix(def,t,rng,excludeSts=[]){
const main=Math.max(...Object.values(def.st??{atk:1}),1);
const pool=AFFIXES.filter((a)=>!excludeSts.includes(a.st));
const a=rng.pick(pool.length?pool:AFFIXES);
let v;
if(a.st==="crit"||a.st==="rate")v=+(a.base*(1+t*0.5)*(0.8+rng.next()*0.6)).toFixed(3);
else v=Math.max(1,Math.round(main*a.base*(1+t)*(0.8+rng.next()*0.6)));
return{st:a.st,v,n:a.name};
}
const AFFIX_MAX=[1,2,2,3,3,3];
function rollArtifact(c,id,rng,opts={}){
const def=itemOf(id);
if(!def||def.k!=="art")return null;
if(c.inv.arts.length>=ART_CAP)return null;
const t=def.t;
const forgeBonus=opts.forge?(pathOf(c.path)?.mods?.forge??0):0;
const nAf=Math.min(AFFIX_MAX[t]??3,([0,1,1,2,2,2][t]??2)+(rng.chance(0.3+forgeBonus)?1:0));
const q=Math.min(5,1+rng.weighted([[0,40],[1,30],[2,18],[3,9],[4,3]])+(opts.forge&&rng.chance(forgeBonus)?1:0));
const af=[];
for(let i=0;i<nAf;i++)af.push(rollAffix(def,t,rng,af.map((x)=>x.st)));
c.ic=(c.ic??0)+1;
const it={iid:c.ic,id,q,af};
c.inv.arts.push(it);
return it;
}
function artifactOf(c,iid){
return c.inv.arts.find((a)=>a.iid===iid)??null;
}
function equip(c,iid){
const it=artifactOf(c,iid);
if(!it)return{ok:false,msg:"没有这件法宝"};
const def=itemOf(it.id);
if(def.t>c.r+1)return{ok:false,msg:"境界不足，无法驾驭此宝"};
c.eq[def.slot]=iid;
return{ok:true,msg:`已祭炼 ${def.name}`};
}
function unequip(c,slot){
if(!["w","a","r"].includes(slot))return{ok:false,msg:"无此部位"};
c.eq[slot]=null;
return{ok:true,msg:"已卸下"};
}
function sellValue(id,n=1,q=1){
const def=itemOf(id);
if(!def)return 0;
return Math.floor(def.v*0.5*n*(1+(q-1)*0.15));
}
function sell(c,id,n){
const def=itemOf(id);
if(!def)return{ok:false,msg:"无此物品"};
if(def.k==="book")return{ok:false,msg:"典籍坊市不收，去拍卖行上拍"};
n=Math.max(1,Math.floor(Number(n)||1));
if(countOf(c,id)<n)return{ok:false,msg:"数量不足"};
removeItems(c,[[id,n]]);
const v=sellValue(id,n);
c.ls+=v;
c.stats.sells=(c.stats.sells??0)+1;
return{ok:true,msg:`卖出 ${def.name}×${n}，得 ${v} 灵石`,ls:v};
}
function sellArtifact(c,iid){
const it=artifactOf(c,iid);
if(!it)return{ok:false,msg:"无此法宝"};
for(const s of["w","a","r"])if(c.eq[s]===iid)c.eq[s]=null;
c.inv.arts=c.inv.arts.filter((a)=>a.iid!==iid);
const v=sellValue(it.id,1,it.q);
c.ls+=v;
c.stats.sells=(c.stats.sells??0)+1;
return{ok:true,msg:`卖出 ${itemOf(it.id).name}，得 ${v} 灵石`,ls:v};
}

function useItem(c,id,now,st,opts={}){
const def=itemOf(id);
if(!def||countOf(c,id)<1)return{ok:false,msg:"没有这件物品"};
if(def.fx?.learn){

const sid=def.fx.learn,isG=sid.startsWith("g_");
const sk=isG?gongfaOf(sid):artOf(sid);
if(sk.path&&sk.path!==c.path)return{ok:false,msg:`此书是${pathOf(sk.path)?.name ?? ""}专修，与你道途不合——不如去坊市上拍，卖给用得上的道友`};
if(isG&&sk.demon&&c.path!=="xie"&&c.r>=1)return{ok:false,msg:"此乃魔功，非邪修不可修——不如去坊市上拍，卖给邪修道友"};
if((isG?c.gfs:c.arts).includes(sid))return{ok:false,msg:"已习得，留着可上拍"};
const r=isG?learnGongfa(c,sid):learnArt(c,sid);
if(!r.ok)return r;
removeItems(c,[[id,1]]);
return{ok:true,msg:r.msg};
}
if(def.fx?.reroot){

removeItems(c,[[id,1]]);
c.tox=Math.min(TOX_MAX,(c.tox??0)+(def.fx.tox??0));
c.root=rollRoot(opts.rng??makeRng(`${c.uid}:${c.sk}:${now}:${c.ac = (c.ac ?? 0) + 1}`));
return{ok:true,msg:`洗髓已毕，灵根重定：${c.root.e.join("")}`,reroot:true};
}
if(def.k==="pill"){
const fx=def.fx;
const pillMult=st?.pathMods?.pill??1;
const toxMult=st?.pathMods?.toxin??1;
const tox=(fx.tox??0)*toxMult;
if(fx.bt!==undefined){
if(fx.realm!==c.r)return{ok:false,msg:`此丹只对${["炼气", "筑基", "金丹", "元婴", "化神", "炼虚", "合体", "大乘", "渡劫"][fx.realm]}期有效`};
if(c.pillBt)return{ok:false,msg:"已服用过突破丹药，药力尚在"};
}
if(c.tox+tox>TOX_MAX&&!fx.detox)return{ok:false,msg:"丹毒已深，再服必走火入魔"};
if(fx.tribHeal&&!c.trib)return{ok:false,msg:"此丹需在渡劫时服用（渡劫界面的定心丹按钮）"};
if(fx.st){
if((c.daily.stp??0)>=STAMINA_PILL_DAILY)return{ok:false,msg:`辟谷之丹一日至多 ${STAMINA_PILL_DAILY} 颗，再服无益`};
if(c.st>=(st?.staminaMax??c.st))return{ok:false,msg:"体力正满，留着路上用"};
}
if(fx.xp&&!fx.heal&&!fx.mp&&!fx.detox&&c.xp>=xpNeed(c)*1.5)return{ok:false,msg:"修为已至此境上限，先突破再服"};
removeItems(c,[[id,1]]);
c.tox=Math.min(TOX_MAX,c.tox+tox);
c.stats.pills++;
const parts=[];
if(fx.xp){

const gain=Math.min(fx.xp*pillMult,xpNeed(c)*1.5-c.xp);
if(gain>0){c.xp+=gain;parts.push(`修为 +${Math.round(gain)}`);}
else parts.push("修为已至此境上限");
}
if(fx.heal){c.hpP=Math.min(1,c.hpP+fx.heal*pillMult);parts.push("气血回复");}
if(fx.mp){c.mpP=Math.min(1,c.mpP+fx.mp*pillMult);parts.push("灵力回复");}
if(fx.st){
const cap=st?.staminaMax??c.st+fx.st;
const got=Math.min(fx.st,Math.max(0,cap-c.st));
c.st+=got;
c.daily.stp=(c.daily.stp??0)+1;
parts.push(`体力 +${got}`);
}
if(fx.rate){c.buffs.push({k:"rate",m:1+(fx.rate.mult-1)*pillMult,from:now,until:now+fx.rate.hours*HOUR,n:def.name});parts.push(`修炼加速 ${fx.rate.hours} 小时`);}
if(fx.bt!==undefined){c.pillBt=fx.bt*pillMult;parts.push(`下次突破成功率 +${Math.round(c.pillBt * 100)}%`);}
if(fx.life){c.lifeBonus=(c.lifeBonus??0)+Math.round(fx.life*pillMult);parts.push(`寿元 +${Math.round(fx.life * pillMult)} 年`);}
if(fx.cure){c.dbf={};parts.push("伤势与心魔尽去");}
if(fx.detox){c.tox=Math.max(0,c.tox-fx.detox);parts.push(`丹毒 -${fx.detox}`);}
return{ok:true,msg:`服下${def.name}：${parts.join("，")}${tox ? `（丹毒 +${Math.round(tox)}）` : ""}`};
}
if(def.k==="egg"){
if(c.pet&&!opts.confirm)return{ok:false,confirm:true,msg:`已有灵兽「${c.pet.name}」，再孵化会让它离去`};
removeItems(c,[[id,1]]);
c.pet={id,name:def.pet.name,elem:def.pet.elem,atk:def.pet.atk,hp:def.pet.hp,lv:0,xp:0,hpP:1,ev:0,trip:null};
return{ok:true,msg:`${def.pet.name}破壳而出，与你结下契约。`};
}
if(def.k==="misc"&&def.fx?.array){
if((c.array??0)>=def.fx.array)return{ok:false,msg:"洞府已有同等或更好的阵法"};
removeItems(c,[[id,1]]);
c.array=def.fx.array;
return{ok:true,msg:"聚灵阵已布下，洞府灵气渐浓。"};
}
if(def.fx?.biguan){
removeItems(c,[[id,1]]);
c.biguan=Math.max(c.biguan??0,now)+def.fx.biguan*HOUR;
return{ok:true,msg:`闭关符已贴，${def.fx.biguan} 小时内离线修炼上限 +12 小时。`};
}
if(def.fx?.ripen){
const plots=(c.farm?.plots??[]).filter((p)=>p&&p.ready>now&&!p.withered);
if(!plots.length)return{ok:false,msg:"灵田里没有正在生长的作物"};
plots.sort((a,b)=>a.ready-b.ready)[0].ready=now;
removeItems(c,[[id,1]]);
return{ok:true,msg:"符光一闪，一块灵田的作物熟了。"};
}
if(def.k==="misc"&&def.fx?.rate){
removeItems(c,[[id,1]]);
c.buffs=(c.buffs??[]).filter((b)=>b.k!=="rate"||(b.until??0)>now);
c.buffs.push({k:"rate",m:def.fx.rate.mult,from:now,until:now+def.fx.rate.hours*HOUR,n:def.name});
return{ok:true,msg:`${def.name}已燃起，${def.fx.rate.hours} 小时内修炼 +${Math.round((def.fx.rate.mult - 1) * 100)}%。`};
}
if(def.k==="misc"&&def.fx?.legacy){
removeItems(c,[[id,1]]);
c.legacyBonus=(c.legacyBonus??0)+def.fx.legacy;
return{ok:true,msg:`传承玉简已炼化，轮回时额外保留 ${def.fx.legacy} 点道统。`};
}
return{ok:false,msg:"此物无法直接使用"};
}
function learnGongfa(c,id){
const g=gongfaOf(id);
if(!GONGFA.some((x)=>x.id===id))return{ok:false,msg:"无此功法"};
if(c.gfs.includes(id))return{ok:false,msg:"已习得"};
c.gfs.push(id);
return{ok:true,msg:`习得功法《${g.name}》`};
}
function learnArt(c,id){
const a=artOf(id);
if(!ARTS.some((x)=>x.id===id))return{ok:false,msg:"无此神通"};
if(c.arts.includes(id))return{ok:false,msg:"已习得"};
c.arts.push(id);
return{ok:true,msg:`习得神通「${a.name}」`};
}

const BOOK_BASIC=new Set(["g_tuna","a_slash","a_fire"]);
function sealBook(c,sid){
sid=String(sid??"");
const isG=sid.startsWith("g_");
if(BOOK_BASIC.has(sid)||!itemOf("b_"+sid))return{ok:false,msg:"此技不可封存"};
if(!(isG?c.gfs:c.arts).includes(sid))return{ok:false,msg:"尚未习得"};
if(isG?c.gf===sid:c.eqArts.includes(sid))return{ok:false,msg:"正在修炼或出战中，先换下再封存"};
if(!addStack(c,"b_"+sid,1))return{ok:false,msg:"行囊已满"};
if(isG)c.gfs=c.gfs.filter((x)=>x!==sid);else c.arts=c.arts.filter((x)=>x!==sid);
return{ok:true,msg:`《${isG ? gongfaOf(sid).name : artOf(sid).name}》已封存成册，可去坊市上拍`};
}
function setGongfa(c,id){
if(!c.gfs.includes(id))return{ok:false,msg:"尚未习得此功法"};
const g=gongfaOf(id);
if(g.path&&g.path!==c.path)return{ok:false,msg:`此功法只有${pathOf(g.path)?.name ?? ""}可修`};
if(g.demon&&c.path!=="xie"&&c.r>=1)return{ok:false,msg:"此乃魔功，非邪修不可修"};
c.gf=id;
return{ok:true,msg:`改修《${g.name}》`};
}
function setArts(c,ids){
if(!Array.isArray(ids)||ids.length<1||ids.length>3)return{ok:false,msg:"神通需装备 1-3 个"};
const uniq=[...new Set(ids.map(String))];
for(const id of uniq){
if(!c.arts.includes(id))return{ok:false,msg:"尚未习得此神通"};
const a=artOf(id);
if(a.path&&a.path!==c.path)return{ok:false,msg:`「${a.name}」只有${pathOf(a.path)?.name ?? ""}可用`};
}
c.eqArts=uniq;
return{ok:true,msg:"神通已调整"};
}
function inventoryView(c){
const stack=Object.entries(c.inv.stack).map(([id,n])=>{
const d=itemOf(id);
return d?{id,n,name:d.name,k:d.k,t:d.t,v:d.v,desc:d.desc,fx:d.fx??null}:null;
}).filter(Boolean);
const arts=c.inv.arts.map((a)=>{
const d=itemOf(a.id);


const qm=1+((a.q??1)-1)*0.08;
const st=d?.st?Object.fromEntries(Object.entries(d.st).map(([k,v])=>[k,v<1?+(v*qm).toFixed(4):Math.round(v*qm)])):d?.st;
return{iid:a.iid,id:a.id,name:d?.name,slot:d?.slot,t:d?.t,v:d?.v??0,q:a.q,qm:+qm.toFixed(2),af:a.af,rn:a.rn??[],st,elem:d?.elem??null,desc:d?.desc,equipped:Object.values(c.eq).includes(a.iid)};
});
return{stack,arts,eq:c.eq,used:bagUsed(c),cap:{stack:STACK_CAP,arts:ART_CAP}};
}

// ---- lib/game/vip.js
export{VIP_MOD,VIP_EN,vipMod};


const VIP=VIP_EN.map((en,i)=>[en,`VIP${i}`]);

const VIP_PERKS=[
[],
["珍宝阁开放","坊市补货 +1 次/日","每日多一张悬赏"],
["拍卖手续费减半","可佩戴会员称号"],
["聚灵香珍宝阁独家","榜单徽记"],
["顶栏金名","改名玉牒独家","珍宝阁法宝保底三星"],
["闭关符独家","周末会员礼 ×2"],
["洗髓丹独家","论道每日 +2 次"],
["传承玉简独家","世界 BOSS 每日 +1 次","珍宝阁每日两件法宝"],
["上拍名额 +2","称号「VIP8 真君」","珍宝阁法宝保底四星"],
["名字流光、灵兽光环","称号「VIP9 至尊」","洞府喜报置顶"],
];
const discS=(d)=>(d>=1?"—":d===0.95?"九五折":d===0.9?"九折":d===0.85?"八五折":d===0.8?"八折":d===0.75?"七五折":"七折");

const VIP_COLS=["等级","能量","修炼","离线","游历","掉落","供奉","兑换","折扣","日礼"];
const VIP_TABLE=()=>VIP_MOD.slice(1).map((m,i)=>[`VIP${i + 1}`,String(VIP_EN[i+1]),`×${m.rate}`,`+${m.off}h`,String(m.exp),`×${m.drop}`,String(m.en),m.enRate>1?`×${m.enRate}`:"—",discS(m.disc),`${m.gift}×`]);
let tableCache=null;
function vipLevel(en){
let lv=0;
for(let i=0;i<VIP.length;i++)if((en|0)>=VIP[i][0])lv=i;
return lv;
}

const vipOf=(c)=>Math.max(0,Math.min(VIP.length-1,c?.vip|0));
function vipView(c,legacy){
const en=legacy?.en|0,lv=vipLevel(en);
const next=lv+1<VIP.length?VIP[lv+1]:null;
return{lv,name:VIP[lv][1],en,next:next?next[1]:null,need:next?next[0]:null,perks:VIP_PERKS.slice(1,lv+1).flat(),now:VIP_MOD[lv],cols:VIP_COLS,table:(tableCache??=VIP_TABLE()),extras:VIP_PERKS.slice(1).map((p,i)=>`VIP${i + 1}：${p.join("、")}`)};
}
const vipTitle=(lv)=>(lv>=9?"VIP9 至尊":lv>=8?"VIP8 真君":lv>=2?`VIP${lv} 道友`:null);

const VS_SLOTS=4; 
const VS_POOL=[
[], 
[["seed+1",3],["p_qingdu",2],["rune",1]],
[["p_xiqi",3],["t_dun",2],["egg+1",1]],
[["m_jinghe",2],["r_ji",1],["r_tu",1],["x_juling",2]], 
[["art",1],["x_gaiming",1]], 
[["t_biguan",3]],
[["p_xisui",1]],
[["x_chuancheng",1],["art",1]], 
[],
[],
];
const VS_EXCLUSIVE=["x_juling","x_gaiming","t_biguan","p_xisui","x_chuancheng"];
const tierOf=(c)=>TIER_OF_REALM[Math.max(0,Math.min(8,c.r|0))]??0;
function resolve(spec,c,rng){
const t=tierOf(c);
if(spec==="seed+1"){const p=ITEMS.filter((i)=>i.fx?.seed&&i.t===Math.min(5,t+1));return p.length?rng.pick(p).id:null;}
if(spec==="rune"){const p=ITEMS.filter((i)=>i.fx?.rune&&i.t<=Math.max(1,t));return p.length?rng.pick(p).id:null;}
if(spec==="egg+1"){const p=ITEMS.filter((i)=>i.k==="egg"&&i.t<=Math.min(4,t+1));return p.length?rng.pick(p).id:null;}
if(spec==="art"){const p=ITEMS.filter((i)=>i.k==="art"&&i.t===Math.min(5,t));return p.length?rng.pick(p).id:null;}
return spec;
}
function vshopStock(c,day){
const lv=vipOf(c);
const rng=makeRng(`vshop:${day}:${c.uid}:${c.r | 0}`);
const pool=VS_POOL.slice(1,lv+1).flat();
const picks=[];
const seen=new Set();
let guard=0;
const slots=vipMod(c).vs;
while(picks.length<slots&&pool.length&&guard++<60){
const[spec,n]=rng.pick(pool);
if(spec==="art"&&picks.filter((p)=>itemOf(p.id)?.k==="art").length>=vipMod(c).arts)continue; 
const id=resolve(spec,c,rng);
if(!id||seen.has(id))continue;
seen.add(id);
const d=itemOf(id);
picks.push({idx:picks.length,id,n,price:Math.round(d.v*1.6)});
}
return picks;
}
function vshopView(c,day){
const lv=vipOf(c);
const bought=c.daily.vshop??{};
return{
lv,name:VIP[lv][1],unlockAt:VIP[1][0],excl:VS_EXCLUSIVE,
stock:vshopStock(c,day).map((s)=>{const d=itemOf(s.id);return{...s,left:Math.max(0,s.n-(bought[s.id]??0)),name:d.name,k:d.k,t:d.t,desc:d.desc};}),
};
}
function vshopBuy(c,idx,day,rng){
const s=vshopStock(c,day)[Number(idx)];
if(!s)return{ok:false,msg:"没有这件珍宝"};
c.daily.vshop=c.daily.vshop??{};
if((c.daily.vshop[s.id]??0)>=s.n)return{ok:false,msg:"已售罄"};
if(c.ls<s.price)return{ok:false,msg:"灵石不足"};
const d=itemOf(s.id);
if(d.k==="art"){
const it=rollArtifact(c,s.id,rng);
if(!it)return{ok:false,msg:"法宝匣已满"};
const q=vipMod(c).q;if((it.q??1)<q)it.q=q; 
}else if(!addStack(c,s.id,1))return{ok:false,msg:"行囊已满"};
c.ls-=s.price;
c.daily.vshop[s.id]=(c.daily.vshop[s.id]??0)+1;
return{ok:true,msg:`珍宝阁购得 ${d.name}，花费 ${s.price} 灵石`};
}

// ---- lib/game/social.js
const MENTOR_MAX=5;
const mentorReward=(r)=>500*Math.max(1,r);
function mentorApply(c,shared,name,now){
if(c.mentor)return{ok:false,msg:"已有师父，一世只拜一次"};
if(c.r>=3)return{ok:false,msg:"元婴之后自成一派，不必拜师"};
const nm=String(name??"").trim();
const p=profiles(shared).find((x)=>x.n===nm&&!x.dead);
if(!p)return{ok:false,msg:"找不到这位道友（须是上过榜的修士）"};
if(String(p.uid)===String(c.uid))return{ok:false,msg:"不能拜自己"};
if((p.r??0)<1||(p.r??0)<=c.r)return{ok:false,msg:"师父须已筑基且境界高于你"};
const n=profiles(shared).filter((x)=>String(x.m??"")===String(p.uid)).length;
if(n>=MENTOR_MAX)return{ok:false,msg:"这位道友门下已满五人"};
c.mentor={uid:p.uid,n:p.n,r0:c.r,t:now};
return{ok:true,msg:`你向${p.n}行了拜师礼。此后每次突破大境界，师徒各得灵石与悟性。`};
}

function apprenticeBreak(c,notes){
if(!c.mentor)return;
const paid=c.mentor.paid??c.mentor.r0??0;
if(c.r<=paid)return;
const ls=mentorReward(c.r),wu=1;
c.ls+=ls;c.wu=(c.wu??0)+wu;c.mentor.paid=c.r;
notes?.push({k:"mentor",v:`师门相庆：灵石 +${ls}，悟性 +${wu}`});
}

function mentorSettle(c,shared,notes){
const kids=profiles(shared).filter((x)=>String(x.m??"")===String(c.uid));
if(!kids.length)return;
c.mentorPaid=c.mentorPaid??{};
for(const k of kids){
if(c.mentorPaid[k.uid]===undefined)c.mentorPaid[k.uid]=Math.min(k.r??0,k.mr??k.r??0); 
if((k.r??0)>c.mentorPaid[k.uid]){
const ls=mentorReward(k.r),wu=1;
c.ls+=ls;c.wu=(c.wu??0)+wu;c.mentorPaid[k.uid]=k.r;
notes?.push({k:"mentor",v:`徒弟${k.n}突破至新境界，为师得灵石 +${ls}，悟性 +${wu}`});
}
}
}
function mentorView(c,shared){
const kids=profiles(shared).filter((x)=>String(x.m??"")===String(c.uid)).map((x)=>({uid:x.uid,n:x.n,r:x.r}));
const master=c.mentor?{...c.mentor,live:profileOf(shared,c.mentor.uid)?.n??c.mentor.n}:null;
return{master,kids,max:MENTOR_MAX,canApply:!c.mentor&&c.r<3,reward:mentorReward(Math.max(1,c.r+1))};
}

// ---- lib/game/cultivate.js
const BREATH_CD=10*60*1000;
const BREATH_DAILY=30;

function breathe(c,now){
if(now-(c.breathAt??0)<BREATH_CD){
const left=Math.ceil((BREATH_CD-(now-c.breathAt)) / 1000);
return{ok:false,msg:`气息未平，${left} 秒后再吐纳`};
}
if(c.daily.breath>=BREATH_DAILY)return{ok:false,msg:"今日吐纳已足，过犹不及"};
if(c.r>=ASCEND_REALM)return{ok:false,msg:"已登仙籍"};
const st=deriveStats(c);
const gain=Math.round(REALMS[c.r].rate*st.rate*0.1);
const need=xpNeed(c);
c.xp=Math.min(need*1.5,c.xp+gain);
c.breathAt=now;
c.daily.breath++;
const ls=1+Math.floor(c.r*1.5);
c.ls+=ls;
c.mpP=Math.min(1,c.mpP+0.1);
return{ok:true,msg:`一呼一吸间，修为 +${gain}，拾得灵石 +${ls}`,gain,ls};
}
function breakthroughChance(c,st){
const base=c.r===0?0.9:Math.max(0.55,0.82-c.r*0.03);
let p=base+st.bt+(c.pillBt??0);
if(c.tox>40)p-=0.1;
if(c.tox>70)p-=0.15;
if(st.injured)p-=0.15;
if(st.heart)p-=0.1;
if(st.qi)p-=0.2;
p+=0.15*(c.btStreak??0); 
return Math.max(0.05,Math.min(0.98,p));
}

function breakthrough(c,now,rng){
if(c.r>=ASCEND_REALM)return{ok:false,msg:"已登仙籍"};
const need=xpNeed(c);
if(c.xp<need)return{ok:false,msg:"修为未满，不可强求"};
if(c.trib)return{ok:false,msg:"天劫当前，先渡劫"};
if(isMajorStep(c.r,c.s))return{ok:false,msg:"需渡劫方可晋升大境界",major:true};
const st=deriveStats(c);
const p=breakthroughChance(c,st);
c.stats.bt++;
c.pillBt=0;
if(rng.chance(p)){
c.xp-=need;
c.s++;
c.hpP=1;c.mpP=1;
c.btStreak=0;
return{ok:true,success:true,msg:`丹田一震，你踏入了${realmName(c.r, c.s)}。`,p};
}
c.stats.btFail++;
c.btStreak=(c.btStreak??0)+1;


c.xp=Math.max(0,c.xp-need*0.1);
c.dbf.qi=now+4*HOUR;
c.hpP=Math.max(0.15,c.hpP-0.25);
const next=Math.round(Math.min(0.98,p+0.15)*100);
return{ok:true,success:false,msg:`灵气逆冲，你走火入魔，修为损失一成，四小时内修炼迟滞。心境却也磨利了一分——下次成功率 ${next}%。`,p};
}
function choosePath(c,id){
const p=pathOf(id);
if(!p)return{ok:false,msg:"无此道途"};
if(c.r<PATH_CHOOSE_REALM)return{ok:false,msg:"筑基之后方可择道"};
if(c.path&&c.path===id)return{ok:false,msg:"已在此道"};
if(c.path){
if(c.r<SUB_CHOOSE_REALM)return{ok:false,msg:"金丹之后方可转修"};
if(c.ls<RESPEC_COST)return{ok:false,msg:`转修需 ${RESPEC_COST} 灵石`};
c.ls-=RESPEC_COST;
c.respec=(c.respec??0)+1;
c.xp=Math.max(0,c.xp*0.5);
}
c.path=id;

c.eqArts=c.eqArts.filter((a)=>{const art=c.arts.includes(a);return art;});
if(c.path==="xie")c.wu=Math.max(0,c.wu-2);
return{ok:true,msg:`自今日起，你是一名${p.name}。`};
}
function chooseSub(c,id){
const s=subOf(id);
if(!s)return{ok:false,msg:"无此副业"};
if(c.r<SUB_CHOOSE_REALM)return{ok:false,msg:"金丹之后方可兼修副业"};
if(c.sub)return{ok:false,msg:"副业已定，不可更改"};
c.sub=id;
return{ok:true,msg:`你兼修${s.name}之道。`};
}

// ---- lib/game/tribulation.js
const BOLTS={1:3,2:5,3:6,4:7,5:8,6:9,7:9,8:9,9:12};



const refHp=(c)=>10*basePower(c.r,c.s);
const ACTIONS=["tank","parry","dodge","artifact","talisman","pill"];
function bolts(target,seed){
const rng=makeRng(seed);
const n=BOLTS[target]??5;
const out=[];
for(let i=0;i<n;i++){
const kind=i===n-1?"心魔":rng.weighted([["雷",6],["火",2],["风",2]]);
const pow=0.22+i*0.045+rng.next()*0.1;
out.push({k:kind,p:+pow.toFixed(3)});
}
return out;
}
function startTribulation(c,now,seed){
if(c.r>=ASCEND_REALM)return{ok:false,msg:"已登仙籍"};
if(c.trib)return{ok:false,msg:"天劫已至"};
if(!isMajorStep(c.r,c.s))return{ok:false,msg:"此非大境界关口"};
if(c.xp<xpNeed(c))return{ok:false,msg:"修为未满"};
const st=deriveStats(c);
if(st.qi)return{ok:false,msg:"走火入魔之际渡劫必死，先养伤"};
const target=c.r+1;
const seedStr=`${seed}:${c.uid}:${c.ac}`;
c.trib={
target,seed:seedStr,i:0,n:(BOLTS[target]??5),hp:1,mp:1,art:1,log:[],t:now,
};
c.ac++;
c.stats.tribs++;
return{ok:true,msg:`乌云聚集，${target >= ASCEND_REALM ? "飞升" : REALMS[target].name}之劫降临！`,trib:tribView(c,st)};
}
function tribView(c,st){
if(!c.trib)return null;
const T=c.trib;
const list=bolts(T.target,T.seed);
const bolt=list[T.i];
const pm=pathOf(c.path)?.trib??{};


let base=refHp(c)*(bolt?.p??0)*1.05*(1-Math.min(0.5,st.trib))*(1-Math.min(0.32,(c.tribStreak??0)*0.08));
if(c.root.t==="bian"&&bolt?.k==="雷")base*=0.75;
if(bolt?.k==="心魔")base*=1-(0.15+Math.min(0.5,(c.wu??0)*0.02)+(st.heart?-0.2:0));
const pctOf=(d)=>Math.min(999,Math.round((d / Math.max(1,st.hp))*100));
const dodgeP=0.3+(pm.dodge??0)+Math.min(0.2,st.spd / (st.spd+200));
const forecast={
tank:pctOf(base*0.8*(1-(pm.tank??0))),
parry:T.mp>=0.1?pctOf(base*0.5*(1-(pm.ward??0))):null,
dodge:T.mp>=0.15?Math.round(dodgeP*100):null,
artifact:T.art>0&&c.eq.w?pctOf(base*0.3):null,
talisman:countOf(c,"t_bilei")>0?0:null,
hp:Math.round(T.hp*100),
};
return{
target:T.target,targetName:T.target>=ASCEND_REALM?"飞升":REALMS[T.target].name,
i:T.i,n:T.n,hp:T.hp,mp:T.mp,art:T.art,bolts:list.slice(0,T.i+1),log:T.log.slice(-6),
can:{
artifact:T.art>0&&!!c.eq.w,
talisman:countOf(c,"t_bilei")>0,
pill:countOf(c,"p_dingxin")>0,
parry:T.mp>=0.1,dodge:T.mp>=0.15,
},
forecast,maxHp:st.hp,maxMp:st.mp,
};
}

function tribStep(c,action,now){
if(!c.trib)return{ok:false,msg:"没有天劫"};
if(!ACTIONS.includes(action))return{ok:false,msg:"无此应对"};
const T=c.trib;
const st=deriveStats(c);
const list=bolts(T.target,T.seed);
const bolt=list[T.i];
const rng=makeRng(`${T.seed}:${T.i}:${action}`);
const pm=pathOf(c.path)?.trib??{}; 
let dmg=refHp(c)*bolt.p*(0.9+rng.next()*0.3);
dmg*=1-Math.min(0.5,st.trib);
dmg*=1-Math.min(0.32,(c.tribStreak??0)*0.08); 
if(c.root.t==="bian"&&bolt.k==="雷")dmg*=0.75;
let note="";
let mpCost=0;
if(bolt.k==="心魔"){

const resist=0.15+Math.min(0.5,(c.wu??0)*0.02)+(st.heart?-0.2:0);
dmg*=1-resist;
note="心魔幻象";
}
switch(action){
case "tank":dmg*=0.8*(1-(pm.tank??0));note+=" 硬抗";break;
case "parry":
if(T.mp>=0.1){mpCost=0.1;dmg*=0.5*(1-(pm.ward??0));note+=" 招架";}
else{note+=" 灵力不足，招架失败";}
break;
case "dodge":{
if(T.mp>=0.15){
mpCost=0.15;
const p=0.3+(pm.dodge??0)+Math.min(0.2,st.spd / (st.spd+200));
if(rng.chance(p)){dmg=0;note+=" 御剑闪避成功";}else{note+=" 闪避失败";}
}else note+=" 灵力不足，无法御剑";
break;
}
case "artifact":
if(T.art>0&&c.eq.w){T.art--;dmg*=0.3;note+=` 祭出${itemOf((c.inv.arts.find((a) => a.iid === c.eq.w) ?? {}).id)?.name ?? "法宝"}`;}
else note+=" 无法宝可祭";
break;
case "talisman":
if(countOf(c,"t_bilei")>0){removeItems(c,[["t_bilei",1]]);dmg=0;note+=" 避雷符化去此雷";}
else note+=" 没有避雷符";
break;
case "pill":
if(countOf(c,"p_dingxin")>0){removeItems(c,[["p_dingxin",1]]);T.hp=Math.min(1,T.hp+0.4);c.tox=Math.min(100,c.tox+5);note+=" 服定心丹回复四成";}
else note+=" 没有定心丹";
break;
}
T.mp=Math.max(0,T.mp-mpCost);
const frac=dmg / st.hp;
T.hp=Math.max(0,T.hp-frac);
T.log.push({i:T.i,k:bolt.k,d:Math.round(dmg),hp:+T.hp.toFixed(3),note:note.trim()});
T.i++;
T.mp=Math.min(1,T.mp+0.04);
if(T.hp<=0){

const target=T.target;
c.trib=null;
c.hpP=0.1;c.mpP=0.2;
c.dbf.injury=now+12*HOUR;


c.xp=Math.max(0,c.xp-xpNeed(c)*0.3);
c.lifeBonus=(c.lifeBonus??0)-5;
c.tribStreak=Math.min(4,(c.tribStreak??0)+1);
c.stats.btFail++;
c.pillBt=0;
return{ok:true,done:true,success:false,msg:`第${T.i}道${bolt.k}劫落下，你倒在了雷光里。重伤、折寿五年，修为损了三成。渡劫的经验刻进了骨头——下次雷劫伤害 -${c.tribStreak * 8}%。`,trib:null,log:T.log};
}
if(T.i>=T.n){

const target=T.target;
c.trib=null;
c.xp=0;
c.r=target;
c.s=0;
c.hpP=Math.max(0.2,T.hp);c.mpP=Math.max(0.2,T.mp);
c.pillBt=0;
c.tribStreak=0;
c.wu+=2;
const ascended=target>=ASCEND_REALM;
if(ascended)c.ascended=true;
return{ok:true,done:true,success:true,target,msg:ascended?"九重天雷散尽，云开处金光万丈。你，飞升了。":`雷劫散去，天地澄明。你已是${realmName(c.r, c.s)}。`,trib:null,log:T.log};
}
return{ok:true,done:false,msg:`第${T.i}道${bolt.k}劫：${note.trim()}，伤 ${Math.round(dmg)}`,trib:tribView(c,st)};
}
function abandonTribulation(c,now){
if(!c.trib)return{ok:false,msg:"没有天劫"};

c.trib=null;
c.hpP=0.05;
c.dbf.injury=now+48*HOUR;
c.xp=Math.max(0,c.xp-xpNeed(c)*0.7);
c.lifeBonus=(c.lifeBonus??0)-20;
return{ok:true,msg:"你逃了。天劫追着你劈了三天三夜。"};
}

