const EVENT_MAP=Object.fromEntries(EVENTS.map((e)=>[e.id,e]));
function eventOf(id){
return EVENT_MAP[id]??null;
}

// ---- lib/game/battle.js
const MAX_TURNS=30;


const PET_SHARE=0.15;
const PET_BITE=0.5;
function elemMult(atkElem,defElem,env){
let m=1;
if(atkElem&&defElem){
if(OVERCOME[atkElem]===defElem)m*=1.3;
else if(OVERCOME[defElem]===atkElem)m*=0.8;
}
if(atkElem==="雷"&&defElem&&defElem!=="雷")m*=1.1; 
if(atkElem==="无")m*=1.05;
const rules=ENV_RULES[env??"arena"]?.bonus??{};
if(atkElem&&rules[atkElem])m*=rules[atkElem];
return m;
}
function cloneUnit(u){
return{
...u,hp:u.hp,mp:u.mp,shield:0,defUp:0,defUpT:0,defDown:0,defDownT:0,slow:0,slowT:0,
dot:[],stun:false,petBoost:0,pet:u.pet?{...u.pet}:null,tals:(u.tals??[]).slice(),
};
}
function chooseArt(u,foe,turn,rng){
const affordable=u.arts.filter((a)=>a.mp<=u.mp);
const pool=affordable.length?affordable:[{id:"a_slash",name:"基础剑式",mult:1,mp:0}];
const hurt=u.hp / u.maxHp<0.35;
const heal=pool.find((a)=>a.effect?.heal);
if(hurt&&heal&&rng.chance(0.7))return heal;
const shield=pool.find((a)=>a.effect?.shield);
if(hurt&&shield&&u.shield<=0&&rng.chance(0.5))return shield;

if(turn<=2){
const setup=pool.find((a)=>{
const fx=a.effect??{};
if(fx.defDown&&foe.defDownT<=0)return true;
if(fx.slow&&foe.slowT<=0)return true;
if(fx.defUp&&u.defUpT<=0)return true;
return false;
});
if(setup&&rng.chance(0.7))return setup;
}
const sorted=pool.filter((a)=>a.mult>=1).sort((a,b)=>b.mult-a.mult);
if(!sorted.length)return pool.filter((a)=>a.mult>0).sort((a,b)=>b.mult-a.mult)[0]??pool[0];
if(sorted.length>1&&rng.chance(0.2))return sorted[1];
return sorted[0];
}
function dealDamage(att,def,rawMult,elem,env,rng,opts={}){
const base=opts.scaleHp?att.maxHp*0.1:att.atk;
let dmg=base*rawMult;
if(elem)dmg*=att.spell;
dmg*=elemMult(elem,def.elem,env);
let defense=def.def*(1+def.defUp-def.defDown);
if(opts.pierce)defense*=1-opts.pierce;
dmg=Math.max(1,dmg-defense*0.5);
dmg*=0.9+rng.next()*0.2;
const crit=rng.chance(att.crit+(opts.crit??0));
if(crit)dmg*=1.6;
dmg=Math.round(dmg);
let absorbed=0;
if(def.shield>0){
absorbed=Math.min(def.shield,dmg);
def.shield-=absorbed;
dmg-=absorbed;
}
def.hp=Math.max(0,def.hp-dmg);
return{dmg,crit,absorbed};
}


function battle(unitA,unitB,rng,env="arena"){
const A=cloneUnit(unitA);
const B=cloneUnit(unitB);
const log=[];
const push=(e)=>log.push({...e,ah:A.hp,bh:B.hp});

for(const[who,me,foe]of[["A",A,B],["B",B,A]]){
for(const tid of me.tals){
const t=itemOf(tid);
if(!t?.fx)continue;
if(t.fx.dmg){
const r=dealDamage(me,foe,t.fx.dmg*(me.talis??1),t.fx.elem,env,rng);
if(t.fx.stun&&rng.chance(t.fx.stun))foe.stun=true;
push({t:0,w:who,s:t.name,d:r.dmg,c:r.crit,e:"符"});
}else if(t.fx.shield){
me.shield+=Math.round(me.maxHp*t.fx.shield);
push({t:0,w:who,s:t.name,e:"护盾"});
}
}
}

if(A.array){B.defDown+=A.array;B.defDownT=3;push({t:0,w:"A",s:"布阵",e:"敌防御下降"});}
if(B.array){A.defDown+=B.array;A.defDownT=3;push({t:0,w:"B",s:"布阵",e:"敌防御下降"});}
let turn=0;
while(turn<MAX_TURNS&&A.hp>0&&B.hp>0){
turn++;
const firstA=A.arts.some((a)=>a.effect?.first)&&!B.arts.some((a)=>a.effect?.first);
const firstB=B.arts.some((a)=>a.effect?.first)&&!A.arts.some((a)=>a.effect?.first);
const spdA=A.spd*(1-A.slow),spdB=B.spd*(1-B.slow);
let order;
if(firstA)order=[["A",A,B],["B",B,A]];
else if(firstB)order=[["B",B,A],["A",A,B]];
else order=spdA>=spdB?[["A",A,B],["B",B,A]]:[["B",B,A],["A",A,B]];
for(const[who,me,foe]of order){
if(me.hp<=0||foe.hp<=0)break;

for(const d of me.dot){
const dd=Math.round(me.maxHp*d.p);
me.hp=Math.max(0,me.hp-dd);
d.t--;
push({t:turn,w:who,s:d.n,d:dd,e:"持续伤害"});
}
me.dot=me.dot.filter((d)=>d.t>0);
if(me.hp<=0)break;
if(me.stun){me.stun=false;push({t:turn,w:who,s:"僵直",e:"无法行动"});continue;}
const art=chooseArt(me,foe,turn,rng);
me.mp=Math.max(0,me.mp-art.mp);
const fx=art.effect??{};

let mult=art.mult;
if(foe.interrupt&&art.mp>=15&&rng.chance(foe.interrupt)){
push({t:turn,w:who,s:art.name,e:"被打断"});
mult=0.3;
}
let entry={t:turn,w:who,s:art.name};
if(mult>0){
const hp0=foe.hp;
const r=dealDamage(me,foe,mult,art.elem??me.elem,env,rng,{crit:art.crit??0,pierce:fx.pierce,scaleHp:art.scale==="hp"});
entry.d=r.dmg;entry.c=r.crit;
if(r.absorbed)entry.e="护盾抵消";


if(foe.pet&&foe.pet.hp>0&&r.dmg>0){
const s=Math.min(Math.ceil(r.dmg*PET_SHARE),foe.pet.hp); 
foe.pet.hp-=s;
foe.hp=Math.max(0,hp0-(r.dmg-s));
if(foe.pet.hp===0)entry.e=`${foe.pet.name}倒下`;
}
if(fx.interrupt&&rng.chance(fx.interrupt)){foe.stun=true;entry.e="雷音震慑";}
if(fx.lifesteal){const h=Math.round(r.dmg*fx.lifesteal);me.hp=Math.min(me.maxHp,me.hp+h);entry.e=`吸血 ${h}`;}
if(fx.selfHurt){me.hp=Math.max(1,me.hp-Math.round(me.maxHp*fx.selfHurt));}
if(fx.stun&&rng.chance(fx.stun)){foe.stun=true;entry.e="敌人僵直";}
if(fx.bleed){foe.dot.push({n:"流血",p:fx.bleed,t:fx.turns??2});entry.e="流血";}
if(fx.burn){foe.dot.push({n:"灼烧",p:fx.burn,t:fx.turns??2});entry.e="灼烧";}
if(fx.slow){foe.slow=Math.max(foe.slow,fx.slow);foe.slowT=fx.turns??2;entry.e="减速";}
if(fx.defDown){foe.defDown+=fx.defDown;foe.defDownT=fx.turns??2;entry.e="破防";}
}
if(fx.heal){const h=Math.round(me.maxHp*fx.heal);me.hp=Math.min(me.maxHp,me.hp+h);entry.e=`回复 ${h}`;}
if(fx.shield){me.shield+=Math.round(me.maxHp*fx.shield);entry.e="护盾";}
if(fx.defUp){me.defUp=fx.defUp;me.defUpT=fx.turns??2;entry.e="防御提升";}
if(fx.petBoost){me.petBoost=fx.petBoost;entry.e="灵兽振奋";}
push(entry);

if(me.pet&&me.pet.hp>0&&foe.hp>0){
const petUnit={atk:me.pet.atk*(1+me.petBoost),maxHp:me.pet.maxHp,spell:1,crit:0.05};
const r=dealDamage(petUnit,foe,PET_BITE,me.pet.elem,env,rng);
me.petBoost=0;
push({t:turn,w:who,s:`${me.pet.name}·撕咬`,d:r.dmg,c:r.crit,e:"灵兽"});
}

if(me.defUpT>0&&--me.defUpT===0)me.defUp=0;
if(me.slowT>0&&--me.slowT===0)me.slow=0;
if(me.defDownT>0&&--me.defDownT===0)me.defDown=0;

me.mp=Math.min(me.maxMp,me.mp+Math.round(me.maxMp*0.05));
}
}
let win;
if(A.hp<=0)win=false;
else if(B.hp<=0)win=true;
else win=A.hp / A.maxHp>=B.hp / B.maxHp;
push({t:turn,w:win?"A":"B",s:win?"胜":"败",e:turn>=MAX_TURNS?"久战不下，以气血论胜负":""});
const petHp=(u)=>(u.pet&&u.pet.maxHp?u.pet.hp / u.pet.maxHp:null);
return{win,turns:turn,log,a:{hp:A.hp,maxHp:A.maxHp,mp:A.mp,maxMp:A.maxMp,petHp:petHp(A)},b:{hp:B.hp,maxHp:B.maxHp,mp:B.mp,maxMp:B.maxMp,petHp:petHp(B)}};
}

// ---- lib/game/farm.js
const FM_MAX=5;
const FM_EV_CHANCE=0.18;
const FM_EV_GRACE=2*HOUR;

const FM_SEED_BY_TIER=["s_lingcao","s_hanlian","s_longxue","s_leijing","s_xianlu","s_xianlu","s_xianlu"];

const FM_MUT={m_lingcao:"m_hanlian",m_hanlian:"m_longxue",m_shuijing:"m_xuanjin",m_longxue:"m_leijing",m_leijing:"m_xianlu",m_xianlu:"m_gangfeng"};
const FM_EVENTS=[
{k:"chong",n:"虫害",cost:{},fix:"你把叶背的虫卵一颗颗捻掉。"},
{k:"han",n:"干旱",cost:{mp:0.1},fix:"你引灵力化雨，田垄重新湿润。"},
{k:"luan",n:"灵气紊乱",cost:{mp:0.2},fix:"你压住乱窜的地气，灵脉复归平顺。"},
{k:"que",n:"灵雀偷食",cost:{ls:[5,20,60,200,600]},fix:"你撒了一把灵石碎屑，灵雀啄食过后飞走了。"},
];
function fmEvOf(k){
return FM_EVENTS.find((e)=>e.k===k)??FM_EVENTS[0];
}
function fmEvCost(e,t){
if(e.cost.ls)return{ls:e.cost.ls[Math.max(0,Math.min(e.cost.ls.length-1,t|0))]};
if(e.cost.mp)return{mp:e.cost.mp};
return{};
}
function fmCostLabel(cost){
if(cost.ls)return `${cost.ls} 灵石`;
if(cost.mp)return `灵力 ${Math.round(cost.mp * 100)}%`;
return "免费";
}

function fmEnsure(c){
const f=(c.farm=c.farm??{n:0,plots:[]});
if(!Array.isArray(f.plots))f.plots=[];
const want=Math.min(FM_MAX,2+(c.r>=1?1:0)+(c.r>=2?1:0)+((c.array??0)>=2?1:0)+vipMod(c).farm);
while(f.plots.length<want)f.plots.push(null);
while(f.plots.length>want&&f.plots[f.plots.length-1]==null)f.plots.pop();
f.n=f.plots.length;
return f;
}
function fmPlot(c,i){
const f=fmEnsure(c);
const k=Math.round(Number(i));
if(!Number.isFinite(k)||k<0||k>=f.plots.length)return{f,k:-1,p:null};
return{f,k,p:f.plots[k]};
}


function farmTick(c,now,notes,prevLast){


if(c.dead)return;
const f=fmEnsure(c);
for(let i=0;i<f.plots.length;i++){
const p=f.plots[i];
if(!p)continue;
p.hurt=p.hurt??0;
p.chk=p.chk??0;
const name=itemOf(p.seed)?.name??"作物";
const totalH=Math.max(1,Math.round((p.ready-p.at) / HOUR));


const hmax=Math.min(Math.floor((now-p.at) / HOUR),totalH);
for(let hh=p.chk+1;hh<=hmax&&p.hurt<2;hh++){
const ts=p.at+hh*HOUR;

if(p.ev&&ts>=Math.min(p.ev.at+FM_EV_GRACE,p.ready)){p.ev=null;p.hurt++;}
if(!p.ev&&p.hurt<2&&hh<totalH){
const rng=makeRng(`farm:${c.uid}:${p.at}:${hh}`);
if(rng.chance(FM_EV_CHANCE)){
const e=FM_EVENTS[rng.int(0,FM_EVENTS.length-1)];
p.ev={k:e.k,at:ts,seen:1};
if(notes)notes.push({k:"farm",v:`灵田 ${i + 1} 的${name}遭了${e.n}，两小时内不理会便会受损。`});
}
}
p.chk=hh;
}
if(p.hurt>=2)p.ev=null;
else if(notes&&p.ready>(prevLast??0)&&p.ready<=now)notes.push({k:"farm",v:`灵田 ${i + 1} 的${name}熟了。`});
}
}
function farmView(c,now){
const f=fmEnsure(c);
const plots=f.plots.map((p,i)=>{
if(!p)return{i,seed:null};
const def=itemOf(p.seed);
const t=def?.t??0;
const mat=def?.fx?.seed??null;
const mdef=mat?itemOf(mat):null;
const span=Math.max(1,p.ready-p.at);
const withered=(p.hurt??0)>=2;
const e=p.ev?fmEvOf(p.ev.k):null;
return{
i,seed:p.seed,name:def?.name??"作物",mat,matName:mdef?.name??"?",t,
pct:Math.max(0,Math.min(100,Math.round(((now-p.at) / span)*100))),
left:Math.max(0,p.ready-now),ready:now>=p.ready&&!withered,
ev:e?{k:e.k,n:e.n,left:Math.max(0,p.ev.at+FM_EV_GRACE-now),cost:fmCostLabel(fmEvCost(e,t))}:null,
hurt:p.hurt??0,withered,
};
});
const seeds=Object.entries(c.inv.stack).map(([id,n])=>({id,n,d:itemOf(id)}))
.filter((x)=>x.d&&x.d.fx&&x.d.fx.seed)
.map((x)=>({id:x.id,name:x.d.name,n:x.n,t:x.d.t,h:x.d.fx.h,mat:itemOf(x.d.fx.seed)?.name??"?"}));
return{n:f.plots.length,plots,seeds,alch:c.path==="dan"};
}
function farmPlant(c,i,seedId,now){
const{f,k,p}=fmPlot(c,i);
if(k<0)return{ok:false,msg:"没有这块灵田"};
if(p)return{ok:false,msg:"这块地里还长着东西"};
const def=itemOf(String(seedId));
if(!def||!def.fx||!def.fx.seed)return{ok:false,msg:"这不是种子"};
if(countOf(c,def.id)<1)return{ok:false,msg:"没有这种种子"};
if((def.t??0)>c.r+1)return{ok:false,msg:"境界不足，此种养不活"};
removeItems(c,[[def.id,1]]);
const h=Math.max(1,def.fx.h??2);
f.plots[k]={seed:def.id,at:now,ready:now+h*HOUR,ev:null,hurt:0,chk:0};
return{ok:true,msg:`${def.name}已下地，${h} 小时后可收。`};
}
function farmTend(c,i){
const{k,p}=fmPlot(c,i);
if(k<0||!p)return{ok:false,msg:"没有这块灵田"};
if((p.hurt??0)>=2)return{ok:false,msg:"这一茬已经枯了，清理了吧"};
if(!p.ev)return{ok:false,msg:"这块田眼下无事"};
const e=fmEvOf(p.ev.k);
const cost=fmEvCost(e,itemOf(p.seed)?.t??0);
if(cost.mp!==undefined){
if((c.mpP??1)<cost.mp)return{ok:false,msg:"灵力不足"};
c.mpP=Math.max(0,(c.mpP??1)-cost.mp);
}
if(cost.ls!==undefined){
if(c.ls<cost.ls)return{ok:false,msg:"灵石不足"};
c.ls-=cost.ls;
}
p.ev=null;
return{ok:true,msg:e.fix};
}
function farmHarvest(c,i,now,rng){
const{f,k,p}=fmPlot(c,i);
if(k<0||!p)return{ok:false,msg:"没有这块灵田"};
if((p.hurt??0)>=2)return{ok:false,msg:"这一茬已经枯了，清理了吧"};
if(now<p.ready)return{ok:false,msg:"还没到时候"};
const def=itemOf(p.seed);
const mdef=def?.fx?.seed?itemOf(def.fx.seed):null;
if(!mdef){f.plots[k]=null;return{ok:false,msg:"这一茬什么也没长出来"};}
const n=Math.max(1,rng.int(2,4)-(p.hurt??0)+(c.path==="dan"?1:0));
const drops=[];
drops.push({id:mdef.id,n,name:mdef.name,t:mdef.t,lost:!addStack(c,mdef.id,n)});
const mut=FM_MUT[mdef.id]?itemOf(FM_MUT[mdef.id]):null;
if(mut&&rng.chance(0.1))drops.push({id:mut.id,n:1,name:mut.name,t:mut.t,lost:!addStack(c,mut.id,1)});
f.plots[k]=null;
c.stats.harvests=(c.stats.harvests??0)+1;
return{ok:true,msg:`收了 ${mdef.name}×${n}${drops.length > 1 ? `，土里还翻出一株${drops[1].name}` : ""}`,drops};
}
function farmClear(c,i){
const{f,k,p}=fmPlot(c,i);
if(k<0||!p)return{ok:false,msg:"这块地本就是空的"};
f.plots[k]=null;
return{ok:true,msg:"枯茎败叶已经清干净了。"};
}

// ---- lib/game/explore.js
const EXPLORE_DAILY=20;
const exploreDaily=(c)=>vipMod(c).exp;

const BOOK_P=(m)=>(m.boss?0.12:0.06);
function giveBook(c,sid,into){const b=itemOf("b_"+sid);if(!b)return false;into.push({id:b.id,n:1,name:b.name,lost:!addStack(c,b.id,1)});return true;}
function monsterUnit(id,rng,tierOverride){
const m=monsterOf(id);
if(!m)return null;
const t=tierOverride??m.t;

const P=basePower(TIER_REALM[t],1)*(m.boss?0.85:t===0?0.6:0.7);
const hp=Math.round(10*P*m.m.hp),mp=Math.round(3*P);
return{
name:m.name,icon:m.icon,id:m.id,hp,maxHp:hp,mp,maxMp:mp,
atk:Math.round(P*m.m.atk),def:Math.round(0.5*P*m.m.def),spd:Math.round((10+6*TIER_REALM[t])*m.m.spd),
crit:0.05,spell:1,elem:m.elem,arts:m.arts.map(artOf),pet:null,path:null,interrupt:0,array:0,talis:1,tals:[],
};
}
function rollDrops(c,m,rng,into){
const mult=dayEvent(c._now??0).drop*vipMod(c).drop; 
for(const[id,p,n]of m.drops??[]){
if(!rng.chance(Math.min(1,p*mult)))continue;
const def=itemOf(id);
if(def){
if(def.k==="art"){const it=rollArtifact(c,id,rng);if(it)into.push({id,n:1,name:def.name,q:it.q});else into.push({id,n:0,name:def.name,lost:true});}
else if(addStack(c,id,n))into.push({id,n,name:def.name});
else into.push({id,n,name:def.name,lost:true});
}else if(id.startsWith("g_")||id.startsWith("a_"))giveBook(c,id,into);
}
for(const a of m.arts??[])if(a!=="a_slash"&&rng.chance(Math.min(1,BOOK_P(m)*mult)))giveBook(c,a,into);
}
function eligible(c,e,region){
if(e.w<=0)return false;
if(e.region!=="any"&&e.region!==region)return false;
if(e.realmMin!==undefined&&c.r<e.realmMin)return false;
if(e.realmMax!==undefined&&c.r>e.realmMax)return false;
if(e.once&&c.once[e.id])return false;
if(e.flag&&!c.flags[e.flag])return false;
return true;
}
function regionsView(c){
return REGIONS.map((r)=>({...r,open:c.r>=r.realm}));
}
function reqOk(c,st,req){
if(!req)return true;
if(req.path&&c.path!==req.path)return false;
if(req.sub&&c.sub!==req.sub)return false;
if(req.elem&&!c.root.e.includes(req.elem))return false;
if(req.realm!==undefined&&c.r<req.realm)return false;
if(req.ls!==undefined&&c.ls<req.ls)return false;
if(req.item&&countOf(c,req.item[0])<req.item[1])return false;
if(req.stat&&(st[req.stat[0]]??0)<req.stat[1])return false;
if(req.flag&&!c.flags[req.flag])return false;
return true;
}
function reqLabel(req){
if(!req)return "";
const parts=[];
if(req.path)parts.push("道途");
if(req.sub)parts.push("副业");
if(req.elem)parts.push(`${req.elem}灵根`);
if(req.realm!==undefined)parts.push("境界");
if(req.ls!==undefined)parts.push(`${req.ls} 灵石`);
if(req.item)parts.push(itemOf(req.item[0])?.name??"物品");
if(req.stat)parts.push(`${{ spd: "速度", atk: "攻击", def: "防御", hp: "气血" }[req.stat[0]] ?? req.stat[0]} ≥ ${req.stat[1]}`);
return parts.join("·");
}
function eventView(c,st){
if(!c.ev)return null;
const e=eventOf(c.ev.id);
if(!e){c.ev=null;return null;}
return{
id:e.id,region:c.ev.region,text:e.text,
opts:e.opts.map((o)=>({id:o.id,label:o.label,ok:reqOk(c,st,o.req),req:reqLabel(o.req),hidden:!!o.hidden})),
};
}

function explore(c,regionId,now,seed){
const region=regionOf(regionId);
if(!region)return{ok:false,msg:"无此地域"};
if(c.r<region.realm)return{ok:false,msg:"境界不足，此地对你太危险"};
if(c.ev)return{ok:false,msg:"眼前的事还没了结"};
if(c.trib)return{ok:false,msg:"天劫当前"};
if(c.st<1)return{ok:false,msg:"体力不支，歇息片刻"};
if(c.daily.exp>=exploreDaily(c))return{ok:false,msg:"今日游历已够，明日再来"};
const st=deriveStats(c);
if(c.hpP<0.15)return{ok:false,msg:"伤势太重，先疗伤（服回血丹，或歇息一小时）"};
const rng=makeRng(`${seed}:${c.uid}:${c.ac}`);
c.ac++;
c.st--;
if(c.st===0||c.stAt===undefined)c.stAt=c.stAt??now;
c.daily.exp++;
c.stats.explores++;

if(c.sub==="shang"&&!c.daily.trade){
c.daily.trade=1;
const te=rng.pick(EVENTS.filter((x)=>x.id.startsWith("sh_trade_")));
if(te){c.ev={id:te.id,region:regionId,seed:`${seed}:${c.ac}`};return{ok:true,event:eventView(c,st)};}
}
const pool=EVENTS.filter((e)=>eligible(c,e,regionId));

if(!pool.length||rng.chance(dayEvent(now).enc)){
const ms=MONSTERS.filter((m)=>m.t===region.tier&&!m.boss);
const m=rng.pick(ms);
c.ev={id:`enc:${m.id}`,region:regionId,seed:`${seed}:${c.ac}`};
return{ok:true,event:encounterView(c,m)};
}
const e=rng.weighted(pool.map((x)=>[x,x.w]));
if(e.once)c.once[e.id]=1;
c.ev={id:e.id,region:regionId,seed:`${seed}:${c.ac}`};
return{ok:true,event:eventView(c,st)};
}
function fleeChance(st){return 0.6+st.spd / (st.spd+100)*0.3;}
function encounterView(c,m){
const st=deriveStats(c);
return{
id:`enc:${m.id}`,region:c.ev.region,enc:{id:m.id,name:m.name,icon:m.icon,elem:m.elem,desc:m.desc},
text:`${m.icon} 你遇到了${m.name}。${m.desc}`,
opts:[
{id:"fight",label:"战",ok:true},
{id:"flee",label:countOf(c,"t_dun")>0?"避开（遁地符，必成）":`避开（成功约 ${Math.round(fleeChance(st) * 100)}%，失败会被追上开打）`,ok:true,req:""},
],
};
}
function runBattle(c,st,monsterId,rng,env,out){
const me=buildUnit(c,st);
me.tals=autoTalismans(c);
const foe=monsterUnit(monsterId,rng);
if(!foe)return false;
const res=battle(me,foe,rng,env);
c.stats.fights++;
for(const t of me.tals)removeItems(c,[[t,1]]);
c.hpP=Math.max(0.05,res.a.hp / res.a.maxHp);
c.mpP=Math.max(0,res.a.mp / res.a.maxMp);
if(c.pet&&res.a.petHp!=null){c.pet.hpP=Math.max(0,res.a.petHp);c.pet.restAt=c._now??c.last;}
const m=monsterOf(monsterId);
out.battle={foe:{id:m.id,name:m.name,icon:m.icon,elem:m.elem,hp:foe.maxHp},me:{name:c.name,r:c.r,hp:me.maxHp},win:res.win,turns:res.turns,log:res.log};
if(res.win){
c.stats.wins++;c.stats.kills++;

c.hpP=Math.min(1,c.hpP+0.2);
const drops=[];
rollDrops(c,m,rng,drops);

const sid=FM_SEED_BY_TIER[Math.min(FM_SEED_BY_TIER.length-1,m.t??0)];
if(sid&&itemOf(sid)&&rng.chance(0.15))drops.push({id:sid,n:1,name:itemOf(sid).name,lost:!addStack(c,sid,1)});
out.drops=(out.drops??[]).concat(drops);
const xp=Math.round(xpNeed(c)*(m.boss?0.08:0.025)*(1+(m.t-c.r)*0.25));
c.xp=Math.min(xpNeed(c)*1.5,c.xp+Math.max(1,xp));
out.xp=(out.xp??0)+Math.max(1,xp);
if(c.pet)petGain(c,Math.round((m.boss?30:10)*vipMod(c).pet),out);
}
return res.win;
}
function autoTalismans(c){
const list=[];
for(const id of["t_tianwang","t_lei","t_huo","t_hu"]){
if(countOf(c,id)>0&&list.length<2)list.push(id);
}
return list;
}
const PET_MAX_LV=20;
function petGain(c,xp,out){
if(!c.pet)return 0;
if((c.pet.lv??0)>=PET_MAX_LV){c.pet.xp=0;return 0;} 
c.pet.xp+=xp;

let up=0;
while(c.pet.lv<PET_MAX_LV){
const need=50*(c.pet.lv+1);
if(c.pet.xp<need)break;
c.pet.xp-=need;c.pet.lv++;up++;
}
if(c.pet.lv>=PET_MAX_LV)c.pet.xp=0;
if(up&&out){
out.lines=out.lines??[];
out.lines.push(`${c.pet.name}升到了 ${c.pet.lv} 级。`);
}
return up;
}

function applyOutcome(c,st,o,rng,out,depth=0){
if(!o||depth>6)return;
out.lines=out.lines??[];
if(o.text)out.lines.push(o.text);
if(o.xp){const need=xpNeed(c);c.xp=Math.max(0,Math.min(need*1.5,c.xp+o.xp));out.xp=(out.xp??0)+o.xp;}
if(o.ls){c.ls=Math.max(0,c.ls+o.ls);out.ls=(out.ls??0)+o.ls;}
if(o.wu){c.wu=Math.max(0,c.wu+o.wu);out.wu=(out.wu??0)+o.wu;}
if(o.hp){c.hpP=Math.max(0.05,Math.min(1,c.hpP+o.hp));}
if(o.mp){c.mpP=Math.max(0,Math.min(1,c.mpP+o.mp));}
if(o.tox){c.tox=Math.max(0,Math.min(100,c.tox+o.tox));}
if(o.life){c.lifeBonus=(c.lifeBonus??0)+o.life;}
if(o.st){c.st=Math.max(0,c.st+o.st);}
if(o.injury){c.dbf.injury=Math.max(c.dbf.injury??0,c._now+24*HOUR);out.lines.push("你受了重伤。");}
if(o.heart){c.dbf.heart=Math.max(c.dbf.heart??0,c._now+48*HOUR);out.lines.push("心魔悄然滋生。");}
if(o.heartCure){delete c.dbf.heart;}
if(o.legacy){c.legacyGain=(c.legacyGain??0)+o.legacy;}
if(o.flag)c.flags[o.flag]=1;
if(o.unflag)delete c.flags[o.unflag];
if(o.items){
for(const[id,n]of o.items){
const def=itemOf(id);
if(!def)continue;
if(n<0){removeItems(c,[[id,-n]]);continue;}
if(def.k==="art"){const it=rollArtifact(c,id,rng);(out.drops=out.drops??[]).push({id,n:1,name:def.name,q:it?.q,lost:!it});}
else{const ok=addStack(c,id,n);(out.drops=out.drops??[]).push({id,n,name:def.name,lost:!ok});}
}
}
for(const[sid,learn]of[[o.gongfa,learnGongfa],[o.art,learnArt]]){
if(!sid)continue;
const r=learn(c,sid);
if(r.ok)out.lines.push(r.msg);
else if(r.msg==="已习得"&&giveBook(c,sid,(out.drops=out.drops??[])))out.lines.push("你早已会此技，便抄成了一册秘籍。");
else out.lines.push(`（${r.msg}）`);
}
if(o.bio)(out.bio=out.bio??[]).push(o.bio);
if(o.chance){
const ok=rng.chance(o.chance.p);
applyOutcome(c,st,ok?o.chance.ok:o.chance.fail,rng,out,depth+1);
}
if(o.battle){
const env=regionOf(c.ev?.region??"qingshan")?.env??"forest";
const mid=typeof o.battle==="string"?o.battle:rng.pick(MONSTERS.filter((m)=>m.t===(o.battle.tier??0)&&!!m.boss===!!o.battle.boss)).id;
const win=runBattle(c,st,mid,rng,env,out);
applyOutcome(c,st,win?o.win:o.lose,rng,out,depth+1);
}
if(o.next)out.next=o.next;
}
function choose(c,optId,now,seed){
if(!c.ev)return{ok:false,msg:"没有待处理的事件"};
const st=deriveStats(c);
const rng=makeRng(`${c.ev.seed}:${optId}`);
const out={lines:[]};
const region=c.ev.region;
if(c.ev.id.startsWith("enc:")){
const mid=c.ev.id.slice(4);
const m=monsterOf(mid);
if(optId==="flee"){
c.ev=null;
if(countOf(c,"t_dun")>0){removeItems(c,[["t_dun",1]]);return{ok:true,result:{lines:["你捏碎遁地符，身形没入土中。它只看见一缕尘烟。"]}};}
if(rng.chance(fleeChance(st)))return{ok:true,result:{lines:["你悄然退走，它没有发现你。"]}};
out.lines.push(`你想悄悄退走，却被${m.name}发现了。它追了上来——避无可避，只能一战。`);
}
const env=regionOf(region)?.env??"forest";
const win=runBattle(c,st,mid,rng,env,out);
out.lines.push(win?`${m.name}倒下了。`:`你败给了${m.name}，仓皇逃离。`);
if(!win)c.hpP=Math.max(0.05,c.hpP);
c.ev=null;
return{ok:true,result:out};
}
const e=eventOf(c.ev.id);
if(!e){c.ev=null;return{ok:false,msg:"事件已消散"};}
const opt=e.opts.find((o)=>o.id===optId);
if(!opt)return{ok:false,msg:"无此选择"};
if(!reqOk(c,st,opt.req))return{ok:false,msg:`条件不足：${reqLabel(opt.req)}`};

const prevSeed=c.ev.seed;
applyOutcome(c,st,opt.out,rng,out); 
c.ev=null;
if(out.next&&eventOf(out.next)){
const ne=eventOf(out.next);
if(ne.once)c.once[ne.id]=1;
c.ev={id:ne.id,region,seed:`${prevSeed}:${out.next}:${c.ac++}`};
out.nextEvent=eventView(c,deriveStats(c));
}
return{ok:true,result:out};
}

