// ---- lib/game/dungeon.js
const DG_ENTRIES=2;
const DG_RELIC_CAP=8;
const DG_LOOT_ARTS=6;

const DG_MAX_TIER=MONSTERS.reduce((t,m)=>(m.boss?t:Math.max(t,m.t)),0);


const DG_TIER_OF_REALM=[0,1,2,3,3,4,5,6,6];
function dgTier(c){
const r=Math.max(0,Math.min(8,c.r|0));
return Math.max(0,Math.min(DG_MAX_TIER,DG_TIER_OF_REALM[r]));
}
function dgUnitLs(tier){
return 10*(1+tier); 
}
function dgHas(dg,id){
return(dg.rel??[]).indexOf(id)>=0;
}
function dgMats(tier){
for(let t=tier;t>=0;t--){
const list=ITEMS.filter((i)=>i.k==="mat"&&i.t===t);
if(list.length)return list;
}
return ITEMS.filter((i)=>i.k==="mat");
}
function dgArts(tier){
for(let t=tier;t>=0;t--){
const list=ITEMS.filter((i)=>i.k==="art"&&i.t===t);
if(list.length)return list;
}
return ITEMS.filter((i)=>i.k==="art");
}
function dgPool(tier){
const list=MONSTERS.filter((m)=>!m.boss&&m.t<=tier);
return list.length?list:MONSTERS.filter((m)=>!m.boss);
}
function dgBossPool(tier){
const list=MONSTERS.filter((m)=>m.boss&&m.t<=tier);
return list.length?list:MONSTERS.filter((m)=>m.boss);
}
function dgLine(dg,s){
if(!s)return;
dg.last=(dg.last??[]).concat([s]).slice(-6);
}


function dgFloorOpts(c,dg,f){
const tier=dgTier(c);
const rng=makeRng(`${dg.sd}:o:${f}`);
if(f>=dg.n){
const m=rng.pick(dgBossPool(tier));
return[{t:"boss",id:m.id,n:`秘境之主 · ${m.name}`,i:m.icon,elem:m.elem,d:m.desc}];
}


const pool=DG_NODES.filter((x)=>f>=x.f).map((x)=>[x,x.w]);
const want=2+(rng.chance(0.45)?1:0);
const picked=[];
let left=pool.slice();
while(picked.length<want&&left.length){
const node=rng.weighted(left);
picked.push(node);
left=left.filter((e)=>e[0].t!==node.t);
}
return picked.map((node)=>{
if(node.t==="mon"||node.t==="elite"){
const m=rng.pick(dgPool(tier));
return{t:node.t,id:m.id,n:node.t==="elite"?`精怪 · ${m.name}`:m.name,i:m.icon,elem:m.elem,d:m.desc};
}
if(node.t==="ev")return{t:"ev",e:Math.floor(rng.next()*DG_EVENTS.length),n:node.n,i:node.i,d:"前方有些说不清的东西。"};
const d={mon:"",chest:"撬开看看，多半有东西。",spring:"回复气血与灵力。",trap:"以速度硬闯，失手要挨一下。",shop:"路遇行商，可换些补给。",relic:"三样机缘，取其一。"}[node.t]??"";
return{t:node.t,n:node.n,i:node.i,d};
});
}

function dgApplyRelics(u,dg){
for(const id of dg.rel??[]){
const r=dgRelicOf(id);
if(!r)continue;
if(r.k==="atk")u.atk=Math.round(u.atk*r.v);
else if(r.k==="def")u.def=Math.round(u.def*r.v);
else if(r.k==="crit")u.crit=+(u.crit+r.v).toFixed(3);
else if(r.k==="spd")u.spd=Math.round(u.spd*r.v);
else if(r.k==="spell")u.spell=+(u.spell*r.v).toFixed(2);
else if(r.k==="hp"){u.maxHp=Math.round(u.maxHp*r.v);u.hp=Math.round(u.hp*r.v);}
else if(r.k==="tal"&&u.tals.length<3)u.tals.push(r.v);
}
return u;
}
function dgUnitFor(c,st,dg){
const u=buildUnit(c,st,{hpFrac:dg.hp,mpFrac:dg.mp});
u.tals=[];
return dgApplyRelics(u,dg);
}





const DG_GAP_POW=0.8;
const DG_REALM_ADJ=[1,1,0.92,0.85,1.08,0.66,0.62,0.66,0.76];
function dgFoe(c,dg,id,rng,kind){
const tier=dgTier(c);
const u=monsterUnit(id,rng,tier);
if(!u)return null;
const df=DG_DIFFS[dg.df]??DG_DIFFS[0];
const r=Math.max(0,Math.min(8,c.r|0));
const gap=basePower(r,c.s??0) / Math.max(1,basePower(TIER_REALM[tier]??r,c.s??0));
let m=(0.5+0.03*dg.f)*df.fm*Math.pow(gap,DG_GAP_POW)*DG_REALM_ADJ[r];
if(kind==="elite")m*=1.2;

u.atk=Math.round(u.atk*m*(tier>=4?0.42:0.5));
u.hp=Math.round(u.hp*m*0.8*(kind==="boss"?1.25:1));
u.maxHp=u.hp;
if(kind==="boss")u.def=Math.round(u.def*0.8);
return u;
}

function dgRollLoot(c,dg,m,rng,times){
const vd=vipMod(c).drop;
const book=(id)=>{if(itemOf("b_"+id)&&dg.loot.b.indexOf(id)<0)dg.loot.b.push(id);};
for(let k=0;k<times;k++){
for(const a of m.arts??[])if(a!=="a_slash"&&rng.chance(Math.min(1,BOOK_P(m)*vd)))book(a);
for(const[id,p,n]of m.drops??[]){
if(!rng.chance(Math.min(1,p*vd)))continue;
const def=itemOf(id);
if(def&&def.k==="art"){
if(dg.loot.a.length>=DG_LOOT_ARTS)continue;
const tmp={inv:{arts:[]},ic:0,path:c.path};
const it=rollArtifact(tmp,id,rng);
if(it)dg.loot.a.push({id,q:it.q,af:it.af});
}else if(def)dg.loot.s[id]=(dg.loot.s[id]??0)+n;
else if(id.startsWith("g_")||id.startsWith("a_"))book(id);
}
}
}
function dgAddArt(c,dg,id,rng){
if(dg.loot.a.length>=DG_LOOT_ARTS)return;
const tmp={inv:{arts:[]},ic:0,path:c.path};
const it=rollArtifact(tmp,id,rng);
if(it)dg.loot.a.push({id,q:it.q,af:it.af});
}
function dgBookName(id){
return(id.startsWith("g_")?gongfaOf(id)?.name:artOf(id)?.name)??id;
}
function dgLootView(dg){
const list=[];
for(const id of Object.keys(dg.loot.s)){const d=itemOf(id);list.push({id,n:dg.loot.s[id],name:d?.name??id,t:d?.t??0});}
for(const a of dg.loot.a){const d=itemOf(a.id);list.push({id:a.id,n:1,q:a.q,name:d?.name??a.id,t:d?.t??0});}
for(const b of dg.loot.b){const d=itemOf("b_"+b);list.push({id:"b_"+b,n:1,name:d?.name??`《${dgBookName(b)}》`,book:1,t:d?.t??3});}
return{n:list.length,a:dg.loot.a.length,list:list.slice(0,8)};
}
function dgGrantRelic(c,dg,rng,lines){
const own=dg.rel??[];
if(own.length>=DG_RELIC_CAP){lines.push("机缘已满，此物与你无缘。");return null;}
const pool=DG_RELICS.filter((r)=>own.indexOf(r.id)<0);
if(!pool.length)return null;
const r=rng.pick(pool);
dg.rel.push(r.id);
lines.push(`获得机缘「${r.n}」（${r.d}）。`);
return r;
}
function dgRelicChoices(dg,rng,n){
const own=dg.rel??[];
const pool=rng.shuffle(DG_RELICS.filter((r)=>own.indexOf(r.id)<0));
return pool.slice(0,n).map((r)=>r.id);
}

function dgAdvance(dg){
dg.pend=null;
dg.pf=null;
dg.f++;
if(dgHas(dg,"chun"))dg.hp=Math.min(1,dg.hp+0.1);
if(dgHas(dg,"quan"))dg.mp=Math.min(1,dg.mp+0.1);
}

function dgBank(c,dg,now,opts={}){
const dead=!!opts.dead,done=!!opts.done;
const stack={},arts=dg.loot.a.slice(),books=dg.loot.b.slice();
const halved=[]; 
for(const id of Object.keys(dg.loot.s)){
const full=dg.loot.s[id];
const n=dead?Math.floor(full / 2):full;
if(n>0)stack[id]=n;
else if(full>0)halved.push({id,n:full});
}
const keep=dead?Math.floor(arts.length / 2):arts.length;
const keptArts=arts.slice(0,keep);
for(const a of arts.slice(keep))halved.push({id:a.id,n:1,q:a.q});
const xp=Math.round(dead?dg.xp / 2:dg.xp);
const ls=Math.round(dead?dg.ls / 2:dg.ls);
const got=[];
for(const id of Object.keys(stack)){
const d=itemOf(id);
got.push({id,n:stack[id],name:d?.name??id,t:d?.t??0,lost:!addStack(c,id,stack[id])});
}
for(const a of keptArts){
const d=itemOf(a.id);
if(c.inv.arts.length>=ART_CAP){got.push({id:a.id,n:1,q:a.q,name:d?.name??a.id,t:d?.t??0,lost:true});continue;}
c.ic=(c.ic??0)+1;
c.inv.arts.push({iid:c.ic,id:a.id,q:a.q,af:a.af});
got.push({id:a.id,n:1,q:a.q,name:d?.name??a.id,t:d?.t??0});
}
for(const x of halved){
const d=itemOf(x.id);
got.push({id:x.id,n:x.n,q:x.q,name:d?.name??x.id,t:d?.t??0,halved:true});
}
const lines=[];
for(const b of books){const d=itemOf("b_"+b);if(d)got.push({id:d.id,n:1,name:d.name,t:d.t,lost:!addStack(c,d.id,1)});}
let xpGot=0;
if(xp>0){const before=c.xp;c.xp=Math.min(xpNeed(c)*1.5,c.xp+xp);xpGot=Math.round(c.xp-before);}
if(xpGot<xp)lines.push("修为已至此境瓶颈，此行所得只入了一部分。");
if(ls>0)c.ls+=ls;


const lostHp=Math.max(0,(dg.h0??dg.hp)-dg.hp);
const lostMp=Math.max(0,(dg.m0??dg.mp)-dg.mp);
c.hpP=dead?0.2:Math.max(0.05,(c.hpP??1)-lostHp);
c.mpP=dead?0.2:Math.max(0,(c.mpP??1)-lostMp);
const depth=done?dg.n:Math.max(0,dg.f-1);
const used=Math.max(0,now-(dg.t0??now));
const wk=weekKey(now);
const best=c.dgBest&&c.dgBest.wk===wk?c.dgBest:null;
if(!best||depth>best.d||(depth===best.d&&used<best.t))c.dgBest={wk,d:depth,t:used};
c.stats.dg=(c.stats.dg??0)+1;
c.dg=null;
return{dead,done,depth,xp:xpGot,ls,drops:got,lines,ms:used};
}

function dgFight(c,st,dg,kind,mid,rng,now,out){
const tier=dgTier(c);
const me=dgUnitFor(c,st,dg);
const foe=dgFoe(c,dg,mid,rng,kind==="mimic"?"elite":kind);
if(!foe)return{ok:false,msg:"此路不通"};
const res=battle(me,foe,rng,"arena");
const m=monsterOf(mid);
c.stats.fights++;
dg.hp=Math.max(0,res.a.hp / res.a.maxHp);
dg.mp=Math.max(0,res.a.mp / res.a.maxMp);
if(c.pet&&res.a.petHp!=null){c.pet.hpP=Math.max(0,res.a.petHp);c.pet.restAt=now;}
out.battle={foe:{id:m.id,name:kind==="mimic"?"拟态宝箱":m.name,icon:kind==="mimic"?"🧰":m.icon,elem:m.elem,hp:foe.maxHp},me:{name:c.name,r:c.r,hp:me.maxHp},win:res.win,turns:res.turns,log:res.log};
const df=DG_DIFFS[dg.df]??DG_DIFFS[0];
if(res.win){
c.stats.wins++;c.stats.kills++;

dg.hp=Math.min(1,dg.hp+0.1);
let times=df.lm*(dgHas(dg,"bao")?2:1)*(kind==="elite"||kind==="boss"?2:1)*(kind==="mimic"?1.5:1);
dgRollLoot(c,dg,m,rng,Math.max(1,Math.round(times)));
const xp=xpNeed(c)*(kind==="boss"?0.1:kind==="mon"?0.02:0.05)*(1+0.05*dg.f)*(dgHas(dg,"wu")?1.5:1);
dg.xp+=xp;
const u=dgUnitLs(tier);
dg.ls+=u*(kind==="boss"?8:kind==="mon"?1:3)*(dgHas(dg,"ju")?1.5:1);
if(c.pet)petGain(c,kind==="boss"?30:10,out);
out.lines.push(`${kind === "mimic" ? "拟态" : m.name}倒下了。`);
if(kind==="elite")dgGrantRelic(c,dg,rng,out.lines);
if(kind==="boss"){
dg.loot.s.m_jinghe=(dg.loot.s.m_jinghe??0)+1;
dgAddArt(c,dg,rng.pick(dgArts(tier)).id,rng);
out.lines.push("秘境之主伏诛，核心与遗宝尽归于你。");
for(const l of out.lines)dgLine(dg,l);
out.bank=dgBank(c,dg,now,{done:true});
return{ok:true,msg:"秘境通关",...out};
}
dgAdvance(dg);
return{ok:true,...out};
}
if(dgHas(dg,"shou")&&!dg.sh){
dg.sh=1;
dg.hp=0.3;
out.lines.push("守护机缘应声而碎，你从鬼门关外爬了回来。");

if(dg.f<dg.n)dgAdvance(dg);
else{dg.pend=null;dg.pf=null;}
return{ok:true,...out};
}
out.lines.push("你倒在了这里。醒来时已在秘境之外，行囊轻了一半。");
for(const l of out.lines)dgLine(dg,l);
out.bank=dgBank(c,dg,now,{dead:true});
return{ok:true,msg:"力竭而返",...out};
}

function dgApplyOut(c,st,dg,o,rng,out,now,depth=0){
if(!o||depth>3)return null;
const tier=dgTier(c);
if(o.text)out.lines.push(o.text);
if(o.hp)dg.hp=Math.max(0.05,Math.min(1,dg.hp+o.hp));
if(o.mp)dg.mp=Math.max(0,Math.min(1,dg.mp+o.mp));
if(o.ls)dg.ls=Math.max(0,dg.ls+o.ls*dgUnitLs(tier)*(o.ls>0&&dgHas(dg,"ju")?1.5:1));
if(o.xp)dg.xp+=xpNeed(c)*o.xp*(dgHas(dg,"wu")?1.5:1);
if(o.relic)dgGrantRelic(c,dg,rng,out.lines);
if(o.item==="mat"){const m=rng.pick(dgMats(tier));dg.loot.s[m.id]=(dg.loot.s[m.id]??0)+1;out.lines.push(`拾得${m.name}。`);}
if(o.p)dgApplyOut(c,st,dg,rng.chance(o.p.chance)?o.p.ok:o.p.fail,rng,out,now,depth+1);
if(o.battle)return dgFight(c,st,dg,"mon",rng.pick(dgPool(tier)).id,rng,now,out);
return null;
}

function dgEnter(c,diff,now){
if(c.dg)return{ok:false,msg:"你已在秘境之中"};
if(c.ev||c.trib)return{ok:false,msg:"眼前的事还没了结"};
const d=DG_DIFFS[Number(diff)|0];
if(!d||Number(diff)!==d.id)return{ok:false,msg:"无此秘境"};
if(c.r<d.realm)return{ok:false,msg:"境界不足，此境凶险"};
if((c.hpP??1)<0.5)return{ok:false,msg:"气血不足五成，先疗伤再进"};
const limit=DG_ENTRIES+(c.sub==="tan"?1:0)+vipMod(c).dg+dayEvent(now).dg;
if((c.daily.dg??0)>=limit)return{ok:false,msg:"今日入秘境的次数已尽"};
c.daily.dg=(c.daily.dg??0)+1;
const sd=String(hashStr(`${c.uid}:${c.sk ?? ""}:${now}:${c.ac}`));
c.ac++;
c.dg={

sd,df:d.id,f:1,n:d.n,hp:c.hpP,mp:c.mpP,h0:c.hpP,m0:c.mpP,rel:[],sh:0,pf:null,
loot:{s:{},a:[],b:[]},xp:0,ls:0,pend:null,last:[`踏入${d.name}秘境，身后石门缓缓合上。`],t0:now,
};
return{ok:true,msg:`入${d.name}秘境`};
}
function dgLeave(c,now){
if(!c.dg)return{ok:false,msg:"你不在秘境中"};
if(c.dg.pend&&c.dg.pend.t==="ev")return{ok:false,msg:"眼前的事还没了结"};
const bank=dgBank(c,c.dg,now,{});
return{ok:true,msg:`收手而归，深入 ${bank.depth} 层`,bank};
}
function dgUse(c,id,now,st){
if(!c.dg)return{ok:false,msg:"你不在秘境中"};
if(id!=="p_huixue"&&id!=="p_huiling")return{ok:false,msg:"秘境中只能服回血丹与回灵丹"};
const dg=c.dg;
if(dg.pf===dg.f)return{ok:false,msg:"本层已服过丹药"};
if(countOf(c,id)<1)return{ok:false,msg:"没有这件物品"};
const def=itemOf(id);
const pm=st?.pathMods?.pill??1,tm=st?.pathMods?.toxin??1;
const tox=(def.fx?.tox??0)*tm;
if(c.tox+tox>TOX_MAX)return{ok:false,msg:"丹毒已深，再服必走火入魔"};
removeItems(c,[[id,1]]);
c.tox=Math.min(TOX_MAX,c.tox+tox);
c.stats.pills++;
dg.pf=dg.f;
if(def.fx?.heal)dg.hp=Math.min(1,dg.hp+def.fx.heal*pm);
if(def.fx?.mp)dg.mp=Math.min(1,dg.mp+def.fx.mp*pm);
dgLine(dg,`服下${def.name}。`);
return{ok:true,msg:`服下${def.name}`};
}
function dgShopGoods(c,dg,rng){
const u=dgUnitLs(dgTier(c));

const relics=(dg.rel??[]).length>=DG_RELIC_CAP?[]:dgRelicChoices(dg,rng,2);
const goods=[{k:"hp",ls:Math.round(2*u)},{k:"mp",ls:Math.round(1.5*u)}].concat(relics.map((id)=>({k:"relic",id,ls:Math.round(4*u)})));
return rng.shuffle(goods).slice(0,3);
}
function dgResolvePend(c,st,dg,i,now,out){
const pend=dg.pend;
const rng=makeRng(`${dg.sd}:p:${dg.f}:${i}`);
if(pend.t==="shop"){
if(i<0){out.lines.push("你摆手谢过，继续往里走。");dgAdvance(dg);return{ok:true,...out};}
const g=pend.g[i];
if(!g)return{ok:false,msg:"无此货物"};

if(g.k!=="hp"&&g.k!=="mp"){
const r0=dgRelicOf(g.id);
if(!r0)return{ok:false,msg:"无此货物"};
if((dg.rel??[]).indexOf(r0.id)>=0)return{ok:false,msg:`${r0.n}你已有了`};
if((dg.rel??[]).length>=DG_RELIC_CAP)return{ok:false,msg:"机缘已满，此物买了也带不走"};
}
if(dg.ls<g.ls)return{ok:false,msg:"本次秘境所得不够付账"};
dg.ls-=g.ls;
if(g.k==="hp"){dg.hp=Math.min(1,dg.hp+0.5);out.lines.push("你就地服下回血丹。");}
else if(g.k==="mp"){dg.mp=Math.min(1,dg.mp+0.5);out.lines.push("你就地服下回灵丹。");}
else{
const r=dgRelicOf(g.id);
dg.rel.push(r.id);
out.lines.push(`买下机缘「${r.n}」（${r.d}）。`);
}
dgAdvance(dg);
return{ok:true,...out};
}
if(pend.t==="relic"){
if(i<0){out.lines.push("你看了两眼，终究没拿。");dgAdvance(dg);return{ok:true,...out};}
const id=pend.r[i];
const r=dgRelicOf(id);
if(!r)return{ok:false,msg:"无此机缘"};
if(dg.rel.length>=DG_RELIC_CAP)out.lines.push("机缘已满，此物与你无缘。");
else if(dg.rel.indexOf(id)<0){dg.rel.push(id);out.lines.push(`取得机缘「${r.n}」（${r.d}）。`);}
dgAdvance(dg);
return{ok:true,...out};
}

const e=DG_EVENTS[pend.e];
const opt=e?.o?.[i];
if(!opt)return{ok:false,msg:"无此选择"};
const fight=dgApplyOut(c,st,dg,opt.out,rng,out,now);
if(fight)return fight;
dgAdvance(dg);
return{ok:true,...out};
}
function dgPick(c,i,now){
if(!c.dg)return{ok:false,msg:"你不在秘境中"};
const dg=c.dg;
const st=deriveStats(c);
const out={lines:[]};
const idx=Number.isFinite(Number(i))?Math.trunc(Number(i)):-1;
const finish=(r)=>{
if(r.ok&&c.dg)for(const l of(r.lines??[]))dgLine(c.dg,l);
return r;
};
if(dg.pend){
const r=dgResolvePend(c,st,dg,idx,now,out);
return r.bank?r:finish(r);
}
const opts=dgFloorOpts(c,dg,dg.f);
if(idx<0||idx>=opts.length)return{ok:false,msg:"无此选择"};
const o=opts[idx];
const rng=makeRng(`${dg.sd}:r:${dg.f}:${idx}`);
const tier=dgTier(c);
const u=dgUnitLs(tier);
if(o.t==="mon"||o.t==="elite"||o.t==="boss"){
const r=dgFight(c,st,dg,o.t,o.id,rng,now,out);
return r.bank?r:finish(r);
}
if(o.t==="chest"){
const key=dgHas(dg,"yao");
const x=rng.next();
if(!key&&x<0.15){
out.lines.push("箱盖翻开，里面长着牙。");
const r=dgFight(c,st,dg,"mimic",rng.pick(dgPool(tier)).id,rng,now,out);
return r.bank?r:finish(r);
}
if(!key&&x<0.2)out.lines.push("箱子空空如也，只有一层浮灰。");
else{
const n=1+(rng.chance(0.5)?1:0)+(key?1:0);
const mats=dgMats(tier);
for(let k=0;k<n;k++){
const m=rng.pick(mats);
const cnt=rng.int(1,3);
dg.loot.s[m.id]=(dg.loot.s[m.id]??0)+cnt;
out.lines.push(`得${m.name}×${cnt}。`);
}
const ls=Math.round(2*u*(1+0.1*dg.f)*(dgHas(dg,"ju")?1.5:1));
dg.ls+=ls;
out.lines.push(`箱底还压着 ${ls} 灵石。`);
}
dgAdvance(dg);
return finish({ok:true,...out});
}
if(o.t==="spring"){
dg.hp=Math.min(1,dg.hp+0.5);
dg.mp=Math.min(1,dg.mp+0.5);
out.lines.push("泉水清冽，气血与灵力都缓了过来。");
dgAdvance(dg);
return finish({ok:true,...out});
}
if(o.t==="trap"){
if(dgHas(dg,"yu"))out.lines.push("轻羽在身，你踏着机关顶端走了过去。");
else{
const p=Math.min(0.95,st.spd / (st.spd+25*(1+tier))*1.1);
if(rng.chance(p)){dg.ls+=u;out.lines.push(`你贴着机关缝隙钻了过去，还顺走 ${u} 灵石。`);}
else{dg.hp=Math.max(0.05,dg.hp-0.25);out.lines.push("机括一响，你被刺了个正着。");}
}
dgAdvance(dg);
return finish({ok:true,...out});
}
if(o.t==="shop"){
dg.pend={t:"shop",g:dgShopGoods(c,dg,rng)};
out.lines.push("一个背着货箱的人靠在石壁上：「买点什么？」");
return finish({ok:true,...out});
}
if(o.t==="relic"){
const r3=dgRelicChoices(dg,rng,3);
if(!r3.length){out.lines.push("此处机缘你已尽得。");dgAdvance(dg);return finish({ok:true,...out});}
dg.pend={t:"relic",r:r3};
out.lines.push("石台上浮着三样东西，只能取一。");
return finish({ok:true,...out});
}
if(o.t==="ev"){
dg.pend={t:"ev",e:o.e};
return finish({ok:true,...out});
}
return{ok:false,msg:"无此选择"};
}

function dgBoard(shared,now){
const wk=weekKey(now);
return profiles(shared).filter((p)=>Array.isArray(p.dgw)&&p.dgw[0]===wk)
.sort((a,b)=>(b.dgw[1]-a.dgw[1])||(a.dgw[2]-b.dgw[2]))
.slice(0,10)
.map((p,i)=>({rank:i+1,uid:p.uid,n:p.n,d:p.dgw[1],t:p.dgw[2]}));
}
function dgPendView(dg){
const p=dg.pend;
if(!p)return null;
if(p.t==="shop")return{t:"shop",g:p.g.map((g)=>({ls:g.ls,n:g.k==="hp"?"回血丹":g.k==="mp"?"回灵丹":dgRelicOf(g.id)?.n??"机缘",d:g.k==="hp"?"气血 +50%":g.k==="mp"?"灵力 +50%":dgRelicOf(g.id)?.d??""}))};
if(p.t==="relic")return{t:"relic",r:p.r.map((id)=>({id,n:dgRelicOf(id)?.n??id,d:dgRelicOf(id)?.d??""}))};
const e=DG_EVENTS[p.e];
return{t:"ev",text:e?.t??"",o:(e?.o??[]).map((x)=>({l:x.l}))};
}
function dungeonView(c,shared,now){
const limit=DG_ENTRIES+(c.sub==="tan"?1:0)+vipMod(c).dg+dayEvent(now).dg;
const wk=weekKey(now);
const v={
left:Math.max(0,limit-(c.daily.dg??0)),limit,
diffs:DG_DIFFS.map((d)=>({id:d.id,name:d.name,n:d.n,lm:d.lm,realm:d.realm,desc:d.desc,ok:c.r>=d.realm})),
best:c.dgBest&&c.dgBest.wk===wk?{d:c.dgBest.d,t:c.dgBest.t}:null,
board:dgBoard(shared,now),run:null,
};
if(!c.dg)return v;
const dg=c.dg;
v.run={
f:dg.f,n:dg.n,df:dg.df,diff:(DG_DIFFS[dg.df]??DG_DIFFS[0]).name,
hp:+dg.hp.toFixed(3),mp:+dg.mp.toFixed(3),xp:Math.round(dg.xp),ls:Math.round(dg.ls),
pillOk:dg.pf!==dg.f,sh:dg.sh?1:0,last:(dg.last??[]).slice(-6),
rel:(dg.rel??[]).map((id)=>({id,n:dgRelicOf(id)?.n??id,d:dgRelicOf(id)?.d??""})),
loot:dgLootView(dg),pend:dgPendView(dg),
opts:dg.pend?[]:dgFloorOpts(c,dg,dg.f).map((o)=>({t:o.t,id:o.id??null,n:o.n,i:o.i,d:o.d??"",elem:o.elem??null})),
};
return v;
}

// ---- lib/game/janitor.js
const JAN_KEY_CAP=100; 
const JAN_SOFT_CAP=88; 
const JAN_BYTE_CAP=160*1024;
const JAN_BOARD_KEEP=50; 
const JAN_AUCTION_DAYS=3; 
const JAN_IDLE_DAYS=3; 



function*expendable(shared,now,aggressive){
const day=dayKey(now),wk=weekKey(now);

for(const e of byPrefix(shared,"wx:"))if(Number(e.key.split(":")[1])<day)yield e.key;

for(const e of byPrefix(shared,"act:"))if((e.value?.day??0)<day)yield e.key;

for(const e of byPrefix(shared,"sbd:"))if(Number(e.key.split(":")[2])<wk)yield e.key;

for(const e of byPrefix(shared,"bd:"))if(Number(e.key.split(":")[1])<day-1)yield e.key;

for(const e of byPrefix(shared,"atk:"))if(!(e.value?.list??[]).some((x)=>now-x.t<ATK_KEEP))yield e.key;

const fold=shared.get("act");
if(fold&&fold.d)for(const e of byPrefix(shared,"act:")){
const uid=e.key.slice(4);
if(fold.d[uid]!==undefined&&fold.d[uid]>=(e.value?.day??0))yield e.key;
}
for(const[pfx,fkPfx,field]of[["bd:","bdx:","d"],["wx:","wxb:","sc"]]){
for(const e of byPrefix(shared,pfx)){
const parts=e.key.split(":"); 
if(parts.length!==3)continue;
const fv=shared.get(fkPfx+parts[1])?.d?.[parts[2]];
if(fv&&(fv[field]??0)>=(e.value?.[field]??0))yield e.key;
}
}




const FOLD_IDLE=shared.size>=JAN_KEY_CAP-5?0:3600_000;
for(const e of byPrefix(shared,"p:")){
const fv=e.value&&shared.get(pxKey(e.value.uid))?.d?.[String(e.value.uid)];
if(fv&&(fv.t??0)>=(e.value.t??0)&&now-(e.value.t??0)>=FOLD_IDLE)yield e.key;
}
const maxT=(rec)=>Math.max(0,...(rec?.list??[]).map((x)=>x.t??0));
for(const e of byPrefix(shared,"atk:")){
const fv=e.value&&shared.get(axKey(e.value.uid))?.d?.[String(e.value.uid)];
if(fv&&maxT(fv)>=maxT(e.value)&&now-maxT(e.value)>=FOLD_IDLE)yield e.key;
}
for(const e of byPrefix(shared,"sc:")){
const fv=e.value&&shared.get(sxKey(e.value.uid))?.d?.[String(e.value.uid)];
if(fv&&(fv.t??0)>=(e.value.t??0)&&now-(e.value.t??0)>=FOLD_IDLE)yield e.key;
}

for(const e of byPrefix(shared,"auction:")){
const a=e.value;
if(a&&a.aid&&a.settled&&shared.get(auxKey(a.uid))?.d?.[String(a.aid)])yield e.key;
}

for(const e of byPrefix(shared,"wxb:"))if(Number(e.key.slice(4))<day)yield e.key;
for(const e of byPrefix(shared,"bdx:"))if(Number(e.key.slice(4))<day-1)yield e.key;
if(!aggressive)return;



const y=byPrefix(shared,`bd:${day - 1}:`).filter((e)=>e.value).sort((a,b)=>(b.value.d??0)-(a.value.d??0));
for(const e of y.slice(JAN_BOARD_KEEP))yield e.key;

for(const e of byPrefix(shared,"auction:")){
const a=e.value;
if(a&&a.settled&&now>(a.end??0)+JAN_AUCTION_DAYS*DAY)yield e.key;
}


const leaders=new Set(byPrefix(shared,"sect:").map((e)=>String(e.value?.leader??"")));


for(const days of[JAN_IDLE_DAYS,1]){
const idle=byPrefix(shared,"p:")
.filter((e)=>e.value&&!e.value.asc&&!leaders.has(String(e.value.uid))&&now-(e.value.t??0)>days*DAY)
.sort((a,b)=>(a.value.t??0)-(b.value.t??0)); 
for(const e of idle){
yield e.key;

const uid=e.value.uid;
if(shared.has(`act:${uid}`))yield `act:${uid}`;
}
}
}

const sizeOf=(v)=>{try{return JSON.stringify(v??null).length;}catch{return 0;}};
function sharedBytes(shared){
let b=0;
for(const[k,v]of shared)b+=k.length+sizeOf(v);
return b;
}
function janitorSweep(shared,now,effects,cap=JAN_SOFT_CAP,byteCap=JAN_BYTE_CAP,budget=Infinity){
const keys=shared.size;
const bytes=sharedBytes(shared);
let n=keys,b=bytes;
const seen=new Set();
let deleted=0;
const take=(key)=>{
if(seen.has(key)||deleted>=budget)return;
seen.add(key);
delShared(effects,key);
deleted++;
n--;b-=key.length+sizeOf(shared.get(key));
};

for(const key of expendable(shared,now,false)){if(deleted>=budget)break;take(key);}

if(n>cap||b>byteCap){
for(const key of expendable(shared,now,true)){
if(deleted>=budget)break;
take(key);
if(n<=cap&&b<=byteCap)break;
}
}
return{keys,bytes,deleted,over:n>cap||b>byteCap};
}

// ---- lib/game/refine.js
const RF_COST=[
[30,[["m_tiekuang",3]]],
[150,[["m_shuijing",2]]],
[600,[["m_xuanjin",2]]],
[2500,[["m_xuanyuan",2],["m_jinghe",1]]],
[10000,[["m_xingchen",2],["m_jinghe",2]]],
[40000,[["m_taixu",2],["m_jinghe",3]]],
];

const RF_STAR_P=[1.0,0.8,0.6,0.4];
const RF_QI_BONUS=0.15;
function rfSockets(t){
return Math.min(3,(t|0)+1);
}
function rfCost(t,mult){
const row=RF_COST[Math.max(0,Math.min(RF_COST.length-1,t|0))];
return{ls:row[0]*mult,mats:row[1].map(([id,n])=>[id,n*mult])};
}
function rfMatView(c,cost){
return cost.mats.map(([id,n])=>({id,name:itemOf(id)?.name??id,n,have:countOf(c,id)}));
}
function rfPay(c,cost){
if(c.ls<cost.ls)return{ok:false,msg:`灵石不足，需 ${cost.ls}`};
if(!hasItems(c,cost.mats))return{ok:false,msg:"材料不足："+cost.mats.map(([id,n])=>`${itemOf(id)?.name ?? id}×${n}`).join("、")};
c.ls-=cost.ls;
removeItems(c,cost.mats);
return{ok:true};
}
function rfStarP(c,q){
return Math.min(1,(RF_STAR_P[q-1]??0)+(c.path==="qi"?RF_QI_BONUS:0));
}

function rfRuneValue(def,t,rdef){
const st=rdef?.fx?.rune;
const rt=rdef?.t??0;
const main=Math.max(...Object.values(def.st??{atk:1}),1);
if(st==="atk"||st==="def")return Math.max(1,Math.round(main*0.05*(1+t)));
if(st==="spd")return 2+2*t;
if(st==="rate")return+(0.015*(1+rt*0.5)).toFixed(3);
return+(0.02*(1+rt*0.5)).toFixed(3); 
}
function rfBump(c){
c.stats.refines=(c.stats.refines??0)+1;
}
function rfSpares(c,it){
const eq=Object.values(c.eq??{});
return c.inv.arts.filter((a)=>a.id===it.id&&a.iid!==it.iid&&!eq.includes(a.iid)).slice().sort((a,b)=>a.q-b.q);
}
const rfShow=(v)=>(v<1&&v>-1?Math.round(v*100)+"%":String(v));
function refineView(c,iid){
const it=artifactOf(c,Number(iid));
if(!it)return null;
const def=itemOf(it.id);
if(!def)return null;
const t=def.t??0;
const one=rfCost(t,1),two=rfCost(t,2);
const af=it.af??[],rn=it.rn??[];
const spares=rfSpares(c,it);
const runes=Object.entries(c.inv.stack).map(([id,n])=>({id,n,d:itemOf(id)}))
.filter((x)=>x.d&&x.d.fx&&x.d.fx.rune)
.map((x)=>({id:x.id,name:x.d.name,n:x.n,st:x.d.fx.rune,v:rfRuneValue(def,t,x.d),had:rn.some((r)=>r.st===x.d.fx.rune)}));
return{
iid:it.iid,id:it.id,name:def.name,slot:def.slot,t,q:it.q,af,rn,lk:it.lk??null,
maxAf:AFFIX_MAX[t]??3,maxRn:rfSockets(t),
reforge:{
ls:one.ls,mats:rfMatView(c,one),can:c.ls>=one.ls&&hasItems(c,one.mats),
lockLs:two.ls,lockMats:rfMatView(c,two),canLock:c.ls>=two.ls&&hasItems(c,two.mats),
},
star:{ls:two.ls,p:rfStarP(c,it.q),cands:spares.map((a)=>({iid:a.iid,q:a.q})),can:it.q<5&&spares.length>0&&c.ls>=two.ls},
runes,
};
}




function refineReforge(c,iid,slot,lock,rng){
const it=artifactOf(c,Number(iid));
if(!it)return{ok:false,msg:"没有这件法宝"};
const def=itemOf(it.id);
if(!def)return{ok:false,msg:"没有这件法宝"};
const t=def.t??0;
it.af=it.af??[];
const maxAf=AFFIX_MAX[t]??3;
const i=Math.round(Number(slot));
if(!Number.isFinite(i)||i<0||i>it.af.length)return{ok:false,msg:"无此词缀槽"};
const isNew=i===it.af.length;
if(isNew&&it.af.length>=maxAf)return{ok:false,msg:`${def.name}最多开 ${maxAf} 条词缀`};
const keepStat=!isNew&&lock!==undefined&&lock!==null&&lock!==""&&lock!==false&&Number(lock)!==0;
const pay=rfPay(c,rfCost(t,keepStat?2:1));
if(!pay.ok)return pay;
const exclude=it.af.filter((_,k)=>k!==i).map((a)=>a.st);
let na;
if(keepStat){
const old=it.af[i];

for(let k=0;k<40;k++){na=rollAffix(def,t,rng,exclude);if(na.st===old.st)break;}
if(!na||na.st!==old.st)na={...old};
if(na.v<old.v)na={...old};
}else{
na=rollAffix(def,t,rng,exclude);
}
if(isNew)it.af.push(na);
else it.af[i]=na;
delete it.lk;
rfBump(c);
return{ok:true,msg:`${def.name}${isNew ? "新生词缀" : keepStat ? "保值重铸" : "重铸"}：${na.n} +${rfShow(na.v)}`};
}

function refineStar(c,iid,withIid,rng){
const it=artifactOf(c,Number(iid));
if(!it)return{ok:false,msg:"没有这件法宝"};
const def=itemOf(it.id);
if(!def)return{ok:false,msg:"没有这件法宝"};
if(it.q>=5)return{ok:false,msg:"已是五星，无可再升"};
const eq=Object.values(c.eq??{});
let s;
if(withIid!==undefined&&withIid!==null&&withIid!==""){
s=artifactOf(c,Number(withIid));
if(!s||s.iid===it.iid)return{ok:false,msg:"请另选一件同名法宝作祭品"};
if(s.id!==it.id)return{ok:false,msg:"祭品须是同一种法宝"};
if(eq.includes(s.iid))return{ok:false,msg:"已祭炼在身的法宝不可作祭品"};
}else{
s=rfSpares(c,it)[0];
if(!s)return{ok:false,msg:"没有可作祭品的同名法宝"};
}
const t=def.t??0;
const cost=rfCost(t,2);
if(c.ls<cost.ls)return{ok:false,msg:`灵石不足，需 ${cost.ls}`};
c.ls-=cost.ls;
c.inv.arts=c.inv.arts.filter((a)=>a.iid!==s.iid);
const p=rfStarP(c,it.q);
const success=rng.chance(p);
if(success)it.q=Math.min(5,it.q+1);
rfBump(c);
return{ok:true,success,p,msg:success?`两宝合一，${def.name}升至 ${it.q} 星。`:`炉火骤熄，祭品化作飞灰，${def.name}纹丝未动。`};
}
function refineRune(c,iid,runeId){
const it=artifactOf(c,Number(iid));
if(!it)return{ok:false,msg:"没有这件法宝"};
const def=itemOf(it.id);
const rdef=itemOf(String(runeId));
if(!rdef||!rdef.fx||!rdef.fx.rune)return{ok:false,msg:"这不是符纹"};
if(countOf(c,rdef.id)<1)return{ok:false,msg:"没有这枚符纹"};
const t=def.t??0;
it.rn=it.rn??[];
if(it.rn.length>=rfSockets(t))return{ok:false,msg:`${def.name}只有 ${rfSockets(t)} 个纹槽`};
if(it.rn.some((r)=>r.st===rdef.fx.rune))return{ok:false,msg:"同类符纹不可重叠"};
removeItems(c,[[rdef.id,1]]);
const v=rfRuneValue(def,t,rdef);
it.rn.push({st:rdef.fx.rune,v,id:rdef.id});
rfBump(c);
return{ok:true,msg:`${rdef.name}没入${def.name}，${rdef.fx.rune} +${rfShow(v)}`};
}
function refineUnrune(c,iid,k){
const it=artifactOf(c,Number(iid));
if(!it)return{ok:false,msg:"没有这件法宝"};
it.rn=it.rn??[];
const i=Math.round(Number(k));
if(!Number.isFinite(i)||i<0||i>=it.rn.length)return{ok:false,msg:"此处没有符纹"};
const gone=it.rn.splice(i,1)[0];
return{ok:true,msg:`${itemOf(gone.id)?.name ?? "符纹"}被剥了下来，纹路碎尽。`};
}

// ---- lib/game/pet.js
const PT_TRIP_DAILY=3;
const PT_HOURS=[4,8,12];
const PT_YIELD={4:0.6,8:1,12:1.5};
const PT_HP_MIN=0.3;
const PT_EVO_LV=[10,20];
const PT_EVO_PREFIX=["","灵·","仙·"];

const PT_MON={e_linghu:"w_hulimei",e_shuijiao:"w_jiao",e_leiying:"w_leiniao",e_xuanwu:"w_xuanwu",e_qilin:"w_xingling"};
const PT_MATS_BY_T=[
["m_lingcao","m_tiekuang","m_yaopi"],
["m_shuijing","m_jiaolin","m_hanlian"],
["m_yaodan","m_longxue","m_xuanjin"],
["m_leijing","m_bingpo","m_xuanyuan"],
["m_xingchen","m_xukong","m_xianlu"],
["m_gangfeng","m_xianjin","m_taixu"],
["m_taixu","m_xianjin","m_gangfeng"],
];
const PT_FEED_CAP=2000;
function ptNeed(lv){
return 50*((lv??0)+1);
}
function ptEvoCost(c){
const eggT=itemOf(c.pet?.id)?.t??0;
return[["m_yaodan",1+eggT],["m_xuanyuan",1+eggT]];
}
function ptFeedXp(def){
if(!def)return 0;
if(def.k==="mat")return Math.min(PT_FEED_CAP,def.v??0);
if(def.k==="pill"&&def.fx&&def.fx.xp)return Math.min(PT_FEED_CAP,Math.round(def.fx.xp / 10));
return 0;
}
function ptDrop(c,id,n,into){
const d=itemOf(id);
if(!d||n<=0)return;
into.push({id,n,name:d.name,t:d.t,lost:!addStack(c,id,n)});
}

function petTick(c,now,notes){
const p=c.pet;
if(!p)return;
p.hpP=p.hpP??1;
if(p.hpP<1){
const h=Math.max(0,(now-(p.restAt??now)) / HOUR);
if(h>0)p.hpP=Math.min(1,p.hpP+h);
}
p.restAt=now;
if(p.trip&&now>=p.trip.ready&&!p.trip.noted){
p.trip.noted=1;
if(notes)notes.push({k:"pet",v:`${p.name}从${regionOf(p.trip.region)?.name ?? "远方"}回来了，带了些东西。`});
}
}
function petView(c,st,now){
const p=c.pet;
const maxed=!!p&&(p.lv??0)>=PET_MAX_LV;
const feed=maxed?[]:Object.entries(c.inv.stack).map(([id,n])=>({id,n,d:itemOf(id)}))
.map((x)=>({id:x.id,n:x.n,name:x.d?.name??x.id,xp:ptFeedXp(x.d)}))
.filter((x)=>x.xp>0).sort((a,b)=>b.xp-a.xp).slice(0,12);
let pet=null;
if(p){
const ev=Math.min(2,p.ev??0);
const lvm=(1+(p.lv??0)*0.1)*[1,1.3,1.69][ev];
const petMult=st?.pathMods?.pet??1;
const rg=p.trip?regionOf(p.trip.region):null;
pet={
id:p.id,name:p.name,elem:p.elem,lv:p.lv??0,xp:p.xp??0,need:ptNeed(p.lv),hpP:p.hpP??1,ev,
mon:PT_MON[p.id]??null,eggTier:itemOf(p.id)?.t??0,
atk:Math.round((st?.atk??0)*p.atk*lvm*petMult),hp:Math.round((st?.hp??0)*p.hp*lvm*petMult),
trip:p.trip?{region:p.trip.region,regionName:rg?.name??p.trip.region,h:p.trip.h,ready:now>=p.trip.ready,left:Math.max(0,p.trip.ready-now)}:null,
canEvolve:ev<2&&(p.lv??0)>=PT_EVO_LV[ev]&&hasItems(c,ptEvoCost(c)),
evoCost:ev<2?ptEvoCost(c).map(([id,n])=>({id,name:itemOf(id)?.name??id,n,have:countOf(c,id)})):[],
evoLv:ev<2?PT_EVO_LV[ev]:null,
};
}
const eggs=Object.entries(c.inv.stack).map(([id,n])=>({id,n,d:itemOf(id)})).filter((x)=>x.d?.k==="egg").map((x)=>({id:x.id,n:x.n,name:x.d.name,pet:x.d.pet.name}));
return{pet,eggs,maxed,regions:REGIONS.map((r)=>({id:r.id,name:r.name,icon:r.icon,tier:r.tier,open:c.r>=r.realm})),feed,hours:PT_HOURS,tripsLeft:Math.max(0,PT_TRIP_DAILY-(c.daily.petTrip??0))};
}
function petSend(c,regionId,hours,now){
const p=c.pet;
if(!p)return{ok:false,msg:"你还没有灵兽"};
if(p.trip)return{ok:false,msg:`${p.name}正在远行`};
const h=Math.round(Number(hours));
if(!PT_HOURS.includes(h))return{ok:false,msg:"只能派遣 4 / 8 / 12 小时"};
const rg=regionOf(String(regionId));
if(!rg)return{ok:false,msg:"无此地域"};
if(c.r<rg.realm)return{ok:false,msg:"此地尚未解锁，灵兽去了回不来"};
if((p.hpP??1)<PT_HP_MIN)return{ok:false,msg:`${p.name}伤势未愈，先让它歇一歇`};
if((c.daily.petTrip??0)>=PT_TRIP_DAILY)return{ok:false,msg:"今日派遣已够，明日再说"};
c.daily.petTrip=(c.daily.petTrip??0)+1;
p.trip={region:rg.id,at:now,ready:now+h*HOUR,h,seed:`${c.uid}:${c.sk ?? ""}:${now}`,noted:0};
return{ok:true,msg:`${p.name}往${rg.name}去了，${h} 小时后回来。`};
}
function petCollect(c,now){
const p=c.pet;
if(!p||!p.trip)return{ok:false,msg:"灵兽不在远行"};
const t=p.trip;
if(now<t.ready)return{ok:false,msg:`${p.name}还没回来`};
const rg=regionOf(t.region);
const tier=Math.max(0,Math.min(PT_MATS_BY_T.length-1,rg?.tier??0));
const rng=makeRng(t.seed);
const out={lines:[],drops:[]};
const total=Math.max(1,Math.round(rng.int(2,5)*(PT_YIELD[t.h]??1)));
const pool=PT_MATS_BY_T[tier];
const kinds=rng.int(1,2);
const first=kinds===1?total:Math.ceil(total / 2);
const i0=rng.int(0,pool.length-1);
ptDrop(c,pool[i0],first,out.drops);
if(kinds>1&&total-first>0)ptDrop(c,pool[(i0+rng.int(1,pool.length-1))%pool.length],total-first,out.drops);
if(rng.chance(0.05)){
const eggs=ITEMS.filter((x)=>x.k==="egg"&&(x.t??0)<=tier);
if(eggs.length){const e=eggs[rng.int(0,eggs.length-1)];ptDrop(c,e.id,1,out.drops);out.lines.push(`${p.name}叼回来一枚${e.name}。`);}
}
if(rng.chance(0.02)){
const k=rng.int(0,3);
if(k===0){ptDrop(c,"m_jinghe",1,out.drops);out.lines.push("它在一处塌了的洞口刨出一枚晶核。");}
else if(k===1){ptDrop(c,"r_ji",1,out.drops);out.lines.push("它咬着一片刻着风纹的碎甲回来。");}
else if(k===2){c.xp=Math.min(xpNeed(c)*1.5,c.xp+200);out.xp=200;out.lines.push("路上有个老道摸了摸它的头，你也觉出一分道理。");}
else{ptDrop(c,"r_tu",1,out.drops);out.lines.push("它从枯坐的骸骨旁衔来一枚吐纳纹。");}
}
petGain(c,10*(t.h??4),out);
p.trip=null;
const got=out.drops.filter((d)=>!d.lost).map((d)=>`${d.name}×${d.n}`).join("、");
return{ok:true,msg:`${p.name}从${rg?.name ?? "远方"}回来了${got ? "：" + got : "，两手空空"}`,drops:out.drops,lines:out.lines};
}
function petFeed(c,itemId){
const p=c.pet;
if(!p)return{ok:false,msg:"你还没有灵兽"};
const def=itemOf(String(itemId));
if(!def||countOf(c,def.id)<1)return{ok:false,msg:"没有这件物品"};
const xp=ptFeedXp(def);
if(xp<=0)return{ok:false,msg:"灵兽不吃这个"};

if((p.lv??0)>=PET_MAX_LV)return{ok:false,msg:`${p.name}已至 ${PET_MAX_LV} 级，再喂也无益`};
removeItems(c,[[def.id,1]]);
const out={lines:[]};
petGain(c,xp,out);
return{ok:true,msg:`${p.name}吃下${def.name}，历练 +${xp}${out.lines.length ? "。" + out.lines.join("") : ""}`,lines:out.lines};
}
function petEvolve(c){
const p=c.pet;
if(!p)return{ok:false,msg:"你还没有灵兽"};
const ev=Math.min(2,p.ev??0);
if(ev>=2)return{ok:false,msg:"它已臻化形之极"};
if((p.lv??0)<PT_EVO_LV[ev])return{ok:false,msg:`需 ${PT_EVO_LV[ev]} 级方可化形`};
const cost=ptEvoCost(c);
if(!hasItems(c,cost))return{ok:false,msg:"材料不足："+cost.map(([id,n])=>`${itemOf(id)?.name ?? id}×${n}`).join("、")};
removeItems(c,cost);
p.ev=ev+1;
const base=String(p.name).replace(/^[灵仙]·/,"");
p.name=PT_EVO_PREFIX[p.ev]+base;
return{ok:true,msg:`${p.name}周身灵光一敛，化形成了。`};
}
function petRelease(c,confirm){
const p=c.pet;
if(!p)return{ok:false,msg:"你还没有灵兽"};
if(p.trip)return{ok:false,msg:"它还在远行的路上"};
if(!confirm)return{ok:false,confirm:true,msg:`放生${p.name}？此后再无瓜葛。`};
const name=p.name;
c.pet=null;
return{ok:true,msg:`${name}回头看了你一眼，转身没入林中。`};
}

